    antialiased_pixels: StorageBuffer<u32, 4194304>,
    progress_pixels: StorageBuffer<OrbitProgress, 4194304>,
    snapshot_pixels: StorageBuffer<u32, 4194304>,
    state: MandelbrotViewState,

    fn initial() -> SurfaceStateEnvelope uses (core::actor::InitialState) {
        initial_state()
    }

    const fn view() -> Surface<MandelbrotParams> {
        Surface {
            extent: Extent::square(2048),
            params: mandelbrot_params(),
        }
    }

    fn initialize_order(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let r: ReferenceControl = self.reference.load(index: 0)
        if r.active_valid == 1 || r.pending == 1 {
            return
        }
        self.orbit.store(
            index: 16390 + invocation.global.x,
            value: order_block(invocation.global.x),
        )
    }

    // Validate a candidate against the latest view before doing more work.
    fn discard_stale_reference(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let control: ReferenceControl = self.reference.load(index: 0)
        if control.pending == 0 {
            return
        }
        let bank: u32 = if control.active == 0 { 1 } else { 0 }
        let candidate: ReferenceAnchor = self.anchor.load(index: bank)
        let delta: Complex<f32> = candidate.delta_from(s)
        if candidate.limit < iteration_limit(s.camera.zoom)
            || max(abs(delta.re), abs(delta.im)) > s.camera.zoom * 0.5
        {
            self.reference.store(index: 0, value: control.cancel_pending())
        }
    }

    fn build_reference(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let previous: ViewCache = self.cache.load(index: 0)
        let initial: ViewCache = self.cache.load(index: 2)
        let previous_preview: PreviewCache = self.preview_cache.load(index: 0)
        let age: f32 = s.input_age()
        let budget: u32 = preview_budget(s.camera.zoom)
        let control: ReferenceControl = self.reference.load(index: 0)
        let active_anchor: ReferenceAnchor = self.anchor.load(index: control.active)
        let delta: Complex<f32> = active_anchor.delta_from(s)
        let target: u32 = iteration_limit(s.camera.zoom)
        let reusable: bool = control.active_valid == 1
            && active_anchor.limit >= target
            && abs(delta.re) <= s.camera.zoom * 0.125
            && abs(delta.im) <= s.camera.zoom * 0.125
        // Keep the active orbit available while a replacement advances in
        // bounded exact-integer batches. Pointer input never queues behind
        // an entire multi-thousand-step reference recurrence.
        let keep_active: bool = if control.pending == 0 { reusable } else { false }
        let defer_rebuild: bool = if control.active_valid == 1 { age < 60.0 } else { false }
        let skip_build: bool = if keep_active { true } else { defer_rebuild }
        if skip_build {
            let preview_bank: u32 = control.preview_bank(s)
            let preview_anchor: ReferenceAnchor = self.anchor.load(index: preview_bank)
            let next_preview: PreviewCache = previous_preview.sync_with_view(
                s,
                control,
                preview_anchor.generation,
                budget,
            )
            self.preview_cache.store(index: 0, value: next_preview)
            self.cache.store(
                index: 0,
                value: previous.sync_for_frame(s, control, next_preview, initial),
            )
        } else {
            let bank: u32 = 1 - control.active
            let base: u32 = bank * 8195
            let existing_pending: ReferenceAnchor = self.anchor.load(index: bank)
            let next_gen: u32 = (if active_anchor.generation > existing_pending.generation {
                active_anchor.generation
            } else {
                existing_pending.generation
            }) + 1
            let pending_anchor: ReferenceAnchor = if control.pending == 0 {
                let created: ReferenceAnchor = ReferenceAnchor::from_state(s, target, next_gen)
                self.anchor.store(index: bank, value: created)
                clear_reference_checkpoint(self.reference_words)
                self.orbit.store(index: base, value: PackedReference::zero())
                created
            } else {
                existing_pending
            }
            let center: Complex<ReferenceReal> = reference_center(pending_anchor)
            let mut z: Complex<ReferenceReal> = if control.pending == 0 {
                Complex::default()
            } else {
                load_reference_checkpoint(self.reference_words, control)
            }
            let mut i: u32 = if control.pending == 0 { 0 } else { control.index }
            let mut step: u32 = 0
            let mut escaped: bool = false
            while step < 64 && i < pending_anchor.limit && !escaped {
                let result: ReferenceStep = reference_step(z, center)
                escaped = result.escaped
                if !escaped {
                    z = result.value
                    self.orbit.store(
                        index: base + i + 1,
                        value: PackedReference::from_fixed(z),
                    )
                    i = i + 1
                }
                step = step + 1
            }
            self.orbit.store(
                index: base + ORBIT_CENTER_INDEX,
                value: PackedReference::from_fixed(center),
            )
            self.orbit.store(
                index: base + ORBIT_META_INDEX,
                value: PackedReference::from_metadata(i + 1, pending_anchor.limit),
            )
            let published: bool = escaped || i >= pending_anchor.limit
            let next_control: ReferenceControl = if published {
                ReferenceControl::publish(bank, i, z.re.sign, z.im.sign, s.clock)
            } else {
                store_reference_checkpoint(self.reference_words, z)
                control.advance_pending(i, z.re.sign, z.im.sign)
            }
            self.reference.store(index: 0, value: next_control)
            // Checkpoints belong to the orbit actually selected for preview.
            // During live input that can still be the active bank while its
            // replacement is being built in the other bank.
            let preview_bank: u32 = next_control.preview_bank(s)
            let preview_anchor: ReferenceAnchor = self.anchor.load(index: preview_bank)
            let next_preview: PreviewCache = previous_preview.sync_with_view(
                s,
                next_control,
                preview_anchor.generation,
                budget,
            )
            self.preview_cache.store(index: 0, value: next_preview)
            let synced_view: ViewCache = previous.sync_for_frame(
                s,
                next_control,
                next_preview,
                initial,
            )
            let next_view: ViewCache = if published {
                synced_view.invalidate_for_new_reference()
            } else {
                synced_view
            }
            self.cache.store(index: 0, value: next_view)
        }
        // Integer center differences are camera work, not per-pixel work.
        // Refresh both live banks after building/publishing the reference.
        let current = self.reference.load(index: 0)
        let full = self.cache.load(index: 1)
        let initial = self.cache.load(index: 2)
        let history = HistoryOffsets::for_view(s, full, initial)
        let mut preview = self.preview_cache.load(index: 0)
        preview.history = history
        self.preview_cache.store(index: 0, value: preview)
        let mut bank: u32 = 0
        while bank < 2 {
            let active = current.active_valid == 1 && bank == current.active
            let pending = current.pending == 1 && bank == 1 - current.active
            if active || pending {
                let offset = self.anchor.load(index: bank).delta_from(s)
                let index = bank * 8195 + ORBIT_META_INDEX
                let metadata = self.orbit.load(index: index)
                self.orbit.store(index: index, value: metadata.with_center_offset(offset))
            }
            bank = bank + 1
        }
    }

    fn advance_preview(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).preview_dirty == 0 {
            return
        }
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 1 || preview.step_target == 0 {
            return
        }
        let s: MandelbrotViewState = self.state
        let x: u32 = invocation.global.x
        let y: u32 = invocation.global.y
        let px: i32 = to_i32(from_i32(__bitcast<u32, i32>(x)) * s.camera.res / 256.0)
        let py: i32 = to_i32(from_i32(__bitcast<u32, i32>(y)) * s.camera.res / 256.0)
        if !s.is_input_settled() {
            let tap: ReprojectionTap = reproject_coarse_pixel(
                s,
                self.cache.load(index: 1),
                self.cache.load(index: 2),
                preview.history,
                px,
                py,
            )
            if tap.reusable {
                return
            }
        }
        let index: u32 = (y << 8) | x
        let old: OrbitProgress = self.preview_progress.load(index: index)
        let saved: OrbitProgress = if old.epoch == preview.epoch {
            old
        } else {
            empty_progress(preview.epoch)
        }
        let done_for_chunk: bool = if saved.is_terminal(preview.budget) {
            true
        } else {
            saved.iteration >= preview.step_target
        }
        if done_for_chunk {
            if old.epoch != preview.epoch {
                self.preview_progress.store(index: index, value: saved)
            }
        } else {
            let next: OrbitProgress = continue_preview_pixel(
                self.orbit,
                preview.reference_bank * 8195,
                s.camera,
                PixelSample::ordered_2x2(px, py),
                preview.step_target,
                preview.step_target,
                preview.prefix_only == 1,
                saved,
            )
            self.preview_progress.store(index: index, value: next)
        }
    }

    fn render_preview(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).preview_dirty == 0 {
            return
        }
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.step_target == 0 {
            return
        }
        let s: MandelbrotViewState = self.state
        let x: u32 = invocation.global.x
        let y: u32 = invocation.global.y
        let index: u32 = (y << 8) | x
        let px: i32 = to_i32(from_i32(__bitcast<u32, i32>(x)) * s.camera.res / 256.0)
        let py: i32 = to_i32(from_i32(__bitcast<u32, i32>(y)) * s.camera.res / 256.0)
        let tap: ReprojectionTap = reproject_coarse_pixel(
            s,
            self.cache.load(index: 1),
            self.cache.load(index: 2),
            preview.history,
            px,
            py,
        )
        let cached: Color = if tap.use_full {
            sample_snapshot(self.snapshot_pixels, tap.sx, tap.sy, tap.old_res)
        } else {
            let scale: f32 = 256.0 / max(tap.old_res, 1.0)
            sample(self.initial_pixels, tap.sx * scale, tap.sy * scale)
        }
        let live_reusable: bool = if tap.reusable { !s.is_input_settled() } else { false }
        if live_reusable {
            self.pixels.store(index: index, value: cached)
        } else {
            let computed: OrbitProgress = self.preview_progress.load(index: index)
            let known_escaped: bool = computed.epoch == preview.epoch
                && computed.is_escaped()
                && !computed.is_glitched()
            let proven_interior: bool = computed.epoch == preview.epoch
                && !computed.is_escaped()
                && !computed.is_glitched()
                && preview.prefix_only == 0
                && computed.iteration >= preview.budget
            if known_escaped || proven_interior {
                let current: Color = unpack_lab(progress_color(computed))
                let result: Color = if tap.reusable {
                    blend(cached, current, progress(s.input_age(), 60.0, 300.0))
                } else {
                    current
                }
                self.pixels.store(index: index, value: result)
            } else if tap.reusable {
                self.pixels.store(index: index, value: cached)
            } else if preview.prefix_only == 0 && computed.is_glitched() {
                self.pixels.store(index: index, value: unpack_lab(interior()))
            } else {
                self.pixels.store(index: index, value: Color::default())
            }
        }
    }

    fn finish_preview(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        if self.cache.load(index: 0).preview_dirty == 0 {
            return
        }
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 1 || preview.step_target == 0 {
            return
        }
        let s: MandelbrotViewState = self.state
        let full: ViewCache = self.cache.load(index: 1)
        let initial: ViewCache = self.cache.load(index: 2)
        if !s.is_input_settled() && (full.completed == 1 || initial.completed == 1) {
            return
        }
        self.preview_cache.store(index: 0, value: preview.commit_step())
    }

    // Preserve the first settled preview before native refinement finishes.
    // Neither this image nor its camera metadata changes while input is live.
    fn cache_initial(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let c: ViewCache = self.cache.load(index: 0)
        let old: ViewCache = self.cache.load(index: 2)
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 0 || !ref_state.can_publish_initial(s, c.epoch, old.epoch) {
            return
        }
        let index: u32 = (invocation.global.y << 8) | invocation.global.x
        self.initial_pixels.store(
            index: index,
            value: self.pixels.load(index: index),
        )
    }

    fn publish_initial(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let c: ViewCache = self.cache.load(index: 0)
        let old: ViewCache = self.cache.load(index: 2)
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 0 || !ref_state.can_publish_initial(s, c.epoch, old.epoch) {
            return
        }
        self.cache.store(index: 2, value: c.as_published_initial())
    }

    fn blur_horizontal(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).blur_dirty == 0 {
            return
        }
        let sigma: f32 = self.reference.load(index: 0).blur_sigma(self.state)
        self.horizontal.store(
            index: (invocation.global.y << 8) | invocation.global.x,
            value: gaussian(
                self.pixels,
                invocation.global.x,
                invocation.global.y,
                sigma,
                false,
            ),
        )
    }

    fn blur_vertical(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).blur_dirty == 0 {
            return
        }
        let sigma: f32 = self.reference.load(index: 0).blur_sigma(self.state)
        self.blurred.store(
            index: (invocation.global.y << 8) | invocation.global.x,
            value: gaussian(
                self.horizontal,
                invocation.global.x,
                invocation.global.y,
                sigma,
                true,
            ),
        )
    }

    // Spatially interleaved phases cover the whole image, rather
    // than sweeping rectangles. Each orbit resumes its own saved recurrence.
    fn restore_oracle(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<16, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        if !s.is_input_settled() {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let history: ViewCache = self.cache.load(index: 1)
        let schedule: RefinementSchedule = RefinementSchedule::for_view(s.camera.zoom, s.camera.res)
        if history.completed == 0 || history.budget < schedule.limit {
            return
        }
        if !same_camera(history, c) {
            return
        }
        let pixel: CohortPixel = schedule.rect_pixel(
            c.cursor,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let saved: OrbitProgress = self.progress_pixels.load(index: index)
        if saved.is_presentable_in(c.epoch) {
            return
        }
        let deep: SampleOracle = self.snapshot_oracle.load(index: index)
        if !deep.is_usable() {
            return
        }
        let preserved: OrbitProgress = OrbitProgress::from_oracle(deep, c.epoch, s.clock)
        let base: u32 = progress_color(preserved)
        self.progress_pixels.store(index: index, value: preserved)
        self.native_pixels.store(index: index, value: base)
        let antialiased: u32 = if history.aa == s.antialias {
            self.snapshot_pixels.load(index: index)
        } else {
            base
        }
        self.antialiased_pixels.store(index: index, value: antialiased)
    }

    // A sparse, full-depth lattice reveals real results while the denser
    // checkpoints are still iterating. It shares their persistent buffers.
    fn seed_refinement(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<16, 16, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        if c.cursor >= 16 || c.completed == 1 {
            return
        }
        let lane: u32 = (invocation.global.y % 4) * 4 + invocation.global.x % 4
        let rank: u32 = c.cursor * 16 + lane
        let block: PackedReference = self.orbit.load(index: 16390 + (rank >> 5))
        let pixel: CohortPixel = seed_pixel(
            block,
            rank,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let old: OrbitProgress = self.progress_pixels.load(index: index)
        if old.is_presentable_in(c.epoch) {
            return
        }
        let saved: OrbitProgress = if old.epoch == c.epoch {
            old
        } else {
            empty_progress(c.epoch)
        }
        let limit: u32 = iteration_limit(s.camera.zoom)
        let next: OrbitProgress = continue_pixel(
            self.orbit,
            ref_state.active * 8195,
            s.camera,
            pixel.sample(),
            limit,
            limit,
            saved,
        )
        self.progress_pixels.store(
            index: index,
            value: next.with_fade_start(s.clock),
        )
        let bits: u32 = progress_color(next)
        self.native_pixels.store(index: index, value: bits)
        self.antialiased_pixels.store(index: index, value: bits)
    }

    fn refine_pixels(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<16, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let schedule: RefinementSchedule = RefinementSchedule::for_view(s.camera.zoom, s.camera.res)
        let pixel: CohortPixel = schedule.rect_pixel(
            c.cursor,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let old: OrbitProgress = self.progress_pixels.load(index: index)
        let saved: OrbitProgress = if old.epoch == c.epoch {
            old
        } else {
            empty_progress(c.epoch)
        }
        if saved.is_terminal(schedule.limit) {
            return
        }
        let next: OrbitProgress = continue_pixel(
            self.orbit,
            ref_state.active * 8195,
            s.camera,
            pixel.sample(),
            schedule.limit,
            2048,
            saved,
        )
        // Once terminal, z_re is free to hold the pixel's fade start time.
        let stored: OrbitProgress = if next.is_terminal(schedule.limit) {
            next.with_fade_start(s.clock)
        } else {
            next
        }
        self.progress_pixels.store(index: index, value: stored)
        let bits: u32 = progress_color(next)
        self.native_pixels.store(index: index, value: bits)
        self.antialiased_pixels.store(index: index, value: bits)
    }

    fn antialias_pixels(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let schedule: RefinementSchedule = RefinementSchedule::for_view(s.camera.zoom, s.camera.res)
        let pixel: CohortPixel = schedule.aa_pixel(
            c.cursor,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let bits: u32 = self.native_pixels.load(index: index)
        let center: Color = unpack_lab(bits)
        let (left_i, right_i, up_i, down_i) = pixel.pixel.clamped_neighbor_indices(s.camera.res)
        let edge: f32 = max(
            max(
                contrast(center, unpack_lab(self.native_pixels.load(index: left_i))),
                contrast(center, unpack_lab(self.native_pixels.load(index: right_i))),
            ),
            max(
                contrast(center, unpack_lab(self.native_pixels.load(index: up_i))),
                contrast(center, unpack_lab(self.native_pixels.load(index: down_i))),
            ),
        )
        if s.antialias >= 0.5 && edge > 0.12 {
            let camera: Camera = s.camera
            let base: u32 = ref_state.active * 8195
            let a: Color = unpack_lab(sample_pixel(
                self.orbit,
                base,
                camera,
                pixel.offset_sample(Vec2 { x: 0.28, y: -0.28 }),
                schedule.limit,
            ))
            let b: Color = unpack_lab(sample_pixel(
                self.orbit,
                base,
                camera,
                pixel.offset_sample(Vec2 { x: -0.28, y: 0.28 }),
                schedule.limit,
            ))
            let averaged: Color = ((center + a) + b) / 3.0
            self.antialiased_pixels.store(
                index: index,
                value: pack_lab(averaged),
            )
        }
    }

    fn finish_refinement(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let end: u32 = RefinementSchedule::for_view(s.camera.zoom, s.camera.res).total_steps()
        if c.cursor >= end {
            return
        }
        self.cache.store(index: 0, value: c.advance_cursor(end))
    }

    fn cache_snapshot(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let c: ViewCache = self.cache.load(index: 0)
        let snapshot: ViewCache = self.cache.load(index: 1)
        if c.completed == 0 || snapshot.epoch == c.epoch {
            return
        }
        // Copy only on publication. Small dispatch also makes the idle guard
        // cheap; coalesced lanes cover the fixed-stride image in 64 strips.
        let lane: u32 = (invocation.global.y << 8) | invocation.global.x
        let mut strip: u32 = 0
        while strip < 64 {
            let index: u32 = lane + (strip << 16)
            let pixel: Pixel = Pixel {
                x: index & 2047,
                y: index >> 11,
            }
            if pixel.in_extent(s.camera.res) {
                self.snapshot_pixels.store(
                    index: index,
                    value: self.antialiased_pixels.load(index: index),
                )
                let result: OrbitProgress = self.progress_pixels.load(index: index)
                self.snapshot_oracle.store(index: index, value: result.to_oracle())
            }
            strip = strip + 1
        }
    }

    fn publish_snapshot(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let c: ViewCache = self.cache.load(index: 0)
        if c.completed == 1 {
            self.cache.store(index: 1, value: c)
        }
    }

    fn display_preview(self, px: i32, py: i32) -> i32 uses (FragmentSurface) {
        let s: MandelbrotViewState = self.state
        let pixel: Pixel = Pixel {
            x: __bitcast<i32, u32>(px) & 2047,
            y: __bitcast<i32, u32>(py) & 2047,
        }
        let index: u32 = pixel.native_index()
        let c: ViewCache = self.cache.load(index: 0)
        let reference_state: ReferenceControl = self.reference.load(index: 0)
        let reveal: f32 = sharpness(reference_state.display_age(s))
        let saved: OrbitProgress = self.progress_pixels.load(index: index)
        if saved.is_presentable_in(c.epoch) {
            let bits: u32 = self.antialiased_pixels.load(index: index)
            let amount: f32 = progress(s.clock - saved.fade_started_at(), 0.0, 350.0) * reveal
            if amount >= 1.0 {
                return display_rgba(unpack_lab(bits))
            }
            let coarse: Color = sample(
                self.blurred,
                from_i32(px) * 256.0 / s.camera.res,
                from_i32(py) * 256.0 / s.camera.res,
            )
            return display_rgba(blend(coarse, unpack_lab(bits), amount))
        }
        let coarse: Color = sample(
            self.blurred,
            from_i32(px) * 256.0 / s.camera.res,
            from_i32(py) * 256.0 / s.camera.res,
        )
        let stride: f32 = from_i32(to_i32((s.camera.res + 511.0) / 512.0))
        let tap: BilinearTap = lattice_tap(px, py, stride, s.camera.res - 1.0)
        let a: OrbitProgress = self.progress_pixels.load(index: tap.i00)
        let b: OrbitProgress = self.progress_pixels.load(index: tap.i10)
        let d: OrbitProgress = self.progress_pixels.load(index: tap.i01)
        let e: OrbitProgress = self.progress_pixels.load(index: tap.i11)
        let ready: bool = a.is_presentable_in(c.epoch)
            && b.is_presentable_in(c.epoch)
            && d.is_presentable_in(c.epoch)
            && e.is_presentable_in(c.epoch)
        if ready {
            let sparse: Color = blend_corners(
                unpack_lab(self.native_pixels.load(index: tap.i00)),
                unpack_lab(self.native_pixels.load(index: tap.i10)),
                unpack_lab(self.native_pixels.load(index: tap.i01)),
                unpack_lab(self.native_pixels.load(index: tap.i11)),
                tap.tx,
                tap.ty,
            )
            let latest_fade: f32 = finite_max(
                finite_max(a.fade_started_at(), b.fade_started_at()),
                finite_max(d.fade_started_at(), e.fade_started_at()),
            )
            let since: f32 = s.clock - latest_fade
            display_rgba(blend(coarse, sparse, progress(since, 0.0, 350.0) * reveal))
        } else {
            display_rgba(coarse)
        }
    }

    fn sync_url(self, event: own SurfaceLocationEvent) -> SurfaceStateEnvelope
        uses (SurfaceLocationTransition)
    {
        SurfaceStateEnvelope { state: sync_url_state(self.state, event) }
    }

    fn contact(self, event: own SurfaceContactEvent) -> SurfaceStateEnvelope
        uses (SurfaceContactTransition)
    {
        SurfaceStateEnvelope { state: contact_transition(self.state, event) }
    }

    fn navigate(self, event: own SurfaceEvent) -> SurfaceStateEnvelope
        uses (SurfaceTransition, SurfaceScheduling<ContinuousFrames>)
    {
        SurfaceStateEnvelope {
            state: transition(self.state, event),
        }
    }
}

reference: actor SmoothPerturbationalMandelbrot uses (
    GpuProgram<WebGpuBackend>,
    SurfaceQuality<SharpBacking>,
    SurfaceRecovery<StandardSurfaceRecovery>,
) {
    orbit: StorageBuffer<PackedReference, ORBIT_CAPACITY>,
    pixels: StorageBuffer<Color, 65536>,
    initial_pixels: StorageBuffer<Color, 65536>,
    preview_progress: StorageBuffer<OrbitProgress, 65536>,
    preview_cache: StorageBuffer<PreviewCache, 1>,
    snapshot_oracle: StorageBuffer<SampleOracle, 4194304>,
    horizontal: StorageBuffer<Color, 65536>,
    blurred: StorageBuffer<Color, 65536>,
    cache: StorageBuffer<ViewCache, 3>,
    anchor: StorageBuffer<ReferenceAnchor, 2>,
    reference: StorageBuffer<ReferenceControl, 1>,
    reference_words: StorageBuffer<u32, 16>,
    native_pixels: StorageBuffer<u32, 4194304>,
    antialiased_pixels: StorageBuffer<u32, 4194304>,
    progress_pixels: StorageBuffer<OrbitProgress, 4194304>,
    snapshot_pixels: StorageBuffer<u32, 4194304>,
    state: MandelbrotViewState,

    fn initial() -> SurfaceStateEnvelope uses (core::actor::InitialState) {
        initial_state()
    }

    const fn view() -> Surface<MandelbrotParams> {
        Surface {
            extent: Extent::square(2048),
            params: mandelbrot_params(),
        }
    }

    fn initialize_order(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let r: ReferenceControl = self.reference.load(index: 0)
        if r.active_valid == 1 || r.pending == 1 {
            return
        }
        self.orbit.store(
            index: 16390 + invocation.global.x,
            value: order_block(invocation.global.x),
        )
    }

    // Validate a candidate against the latest view before doing more work.
    fn discard_stale_reference(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let control: ReferenceControl = self.reference.load(index: 0)
        if control.pending == 0 {
            return
        }
        let bank: u32 = if control.active == 0 { 1 } else { 0 }
        let candidate: ReferenceAnchor = self.anchor.load(index: bank)
        let delta: Complex<f32> = candidate.delta_from(s)
        if candidate.limit < iteration_limit(s.camera.zoom)
            || max(abs(delta.re), abs(delta.im)) > s.camera.zoom * 0.5
        {
            self.reference.store(index: 0, value: control.cancel_pending())
        }
    }

    fn build_reference(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let previous: ViewCache = self.cache.load(index: 0)
        let initial: ViewCache = self.cache.load(index: 2)
        let previous_preview: PreviewCache = self.preview_cache.load(index: 0)
        let age: f32 = s.input_age()
        let budget: u32 = preview_budget(s.camera.zoom)
        let control: ReferenceControl = self.reference.load(index: 0)
        let active_anchor: ReferenceAnchor = self.anchor.load(index: control.active)
        let delta: Complex<f32> = active_anchor.delta_from(s)
        let target: u32 = iteration_limit(s.camera.zoom)
        let reusable: bool = control.active_valid == 1
            && active_anchor.limit >= target
            && abs(delta.re) <= s.camera.zoom * 0.125
            && abs(delta.im) <= s.camera.zoom * 0.125
        // Keep the active orbit available while a replacement advances in
        // bounded exact-integer batches. Pointer input never queues behind
        // an entire multi-thousand-step reference recurrence.
        let keep_active: bool = if control.pending == 0 { reusable } else { false }
        let defer_rebuild: bool = if control.active_valid == 1 { age < 60.0 } else { false }
        let skip_build: bool = if keep_active { true } else { defer_rebuild }
        if skip_build {
            let preview_bank: u32 = control.preview_bank(s)
            let preview_anchor: ReferenceAnchor = self.anchor.load(index: preview_bank)
            let next_preview: PreviewCache = previous_preview.sync_with_view(
                s,
                control,
                preview_anchor.generation,
                budget,
            )
            self.preview_cache.store(index: 0, value: next_preview)
            self.cache.store(
                index: 0,
                value: previous.sync_for_frame(s, control, next_preview, initial),
            )
        } else {
            let bank: u32 = 1 - control.active
            let base: u32 = bank * 8195
            let existing_pending: ReferenceAnchor = self.anchor.load(index: bank)
            let next_gen: u32 = (if active_anchor.generation > existing_pending.generation {
                active_anchor.generation
            } else {
                existing_pending.generation
            }) + 1
            let pending_anchor: ReferenceAnchor = if control.pending == 0 {
                let created: ReferenceAnchor = ReferenceAnchor::from_state(s, target, next_gen)
                self.anchor.store(index: bank, value: created)
                clear_reference_checkpoint(self.reference_words)
                self.orbit.store(index: base, value: PackedReference::zero())
                created
            } else {
                existing_pending
            }
            let center: Complex<ReferenceReal> = reference_center(pending_anchor)
            let mut z: Complex<ReferenceReal> = if control.pending == 0 {
                Complex::default()
            } else {
                load_reference_checkpoint(self.reference_words, control)
            }
            let mut i: u32 = if control.pending == 0 { 0 } else { control.index }
            let mut step: u32 = 0
            let mut escaped: bool = false
            while step < 64 && i < pending_anchor.limit && !escaped {
                let result: ReferenceStep = reference_step(z, center)
                escaped = result.escaped
                if !escaped {
                    z = result.value
                    self.orbit.store(
                        index: base + i + 1,
                        value: PackedReference::from_fixed(z),
                    )
                    i = i + 1
                }
                step = step + 1
            }
            self.orbit.store(
                index: base + ORBIT_CENTER_INDEX,
                value: PackedReference::from_fixed(center),
            )
            self.orbit.store(
                index: base + ORBIT_META_INDEX,
                value: PackedReference::from_metadata(i + 1, pending_anchor.limit),
            )
            let published: bool = escaped || i >= pending_anchor.limit
            let next_control: ReferenceControl = if published {
                ReferenceControl::publish(bank, i, z.re.sign, z.im.sign, s.clock)
            } else {
                store_reference_checkpoint(self.reference_words, z)
                control.advance_pending(i, z.re.sign, z.im.sign)
            }
            self.reference.store(index: 0, value: next_control)
            // Checkpoints belong to the orbit actually selected for preview.
            // During live input that can still be the active bank while its
            // replacement is being built in the other bank.
            let preview_bank: u32 = next_control.preview_bank(s)
            let preview_anchor: ReferenceAnchor = self.anchor.load(index: preview_bank)
            let next_preview: PreviewCache = previous_preview.sync_with_view(
                s,
                next_control,
                preview_anchor.generation,
                budget,
            )
            self.preview_cache.store(index: 0, value: next_preview)
            let synced_view: ViewCache = previous.sync_for_frame(
                s,
                next_control,
                next_preview,
                initial,
            )
            let next_view: ViewCache = if published {
                synced_view.invalidate_for_new_reference()
            } else {
                synced_view
            }
            self.cache.store(index: 0, value: next_view)
        }
        // Integer center differences are camera work, not per-pixel work.
        // Refresh both live banks after building/publishing the reference.
        let current = self.reference.load(index: 0)
        let full = self.cache.load(index: 1)
        let initial = self.cache.load(index: 2)
        let history = HistoryOffsets::for_view(s, full, initial)
        let mut preview = self.preview_cache.load(index: 0)
        preview.history = history
        self.preview_cache.store(index: 0, value: preview)
        let mut bank: u32 = 0
        while bank < 2 {
            let active = current.active_valid == 1 && bank == current.active
            let pending = current.pending == 1 && bank == 1 - current.active
            if active || pending {
                let offset = self.anchor.load(index: bank).delta_from(s)
                let index = bank * 8195 + ORBIT_META_INDEX
                let metadata = self.orbit.load(index: index)
                self.orbit.store(index: index, value: metadata.with_center_offset(offset))
            }
            bank = bank + 1
        }
    }

    fn advance_preview(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).preview_dirty == 0 {
            return
        }
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 1 || preview.step_target == 0 {
            return
        }
        let s: MandelbrotViewState = self.state
        let x: u32 = invocation.global.x
        let y: u32 = invocation.global.y
        let px: i32 = to_i32(from_i32(__bitcast<u32, i32>(x)) * s.camera.res / 256.0)
        let py: i32 = to_i32(from_i32(__bitcast<u32, i32>(y)) * s.camera.res / 256.0)
        if !s.is_input_settled() {
            let tap: ReprojectionTap = reproject_coarse_pixel(
                s,
                self.cache.load(index: 1),
                self.cache.load(index: 2),
                preview.history,
                px,
                py,
            )
            if tap.reusable {
                return
            }
        }
        let index: u32 = (y << 8) | x
        let old: OrbitProgress = self.preview_progress.load(index: index)
        let saved: OrbitProgress = if old.epoch == preview.epoch {
            old
        } else {
            empty_progress(preview.epoch)
        }
        let done_for_chunk: bool = if saved.is_terminal(preview.budget) {
            true
        } else {
            saved.iteration >= preview.step_target
        }
        if done_for_chunk {
            if old.epoch != preview.epoch {
                self.preview_progress.store(index: index, value: saved)
            }
        } else {
            let next: OrbitProgress = continue_preview_pixel(
                self.orbit,
                preview.reference_bank * 8195,
                s.camera,
                PixelSample::ordered_2x2(px, py),
                preview.step_target,
                preview.step_target,
                preview.prefix_only == 1,
                saved,
            )
            self.preview_progress.store(index: index, value: next)
        }
    }

    fn render_preview(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).preview_dirty == 0 {
            return
        }
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.step_target == 0 {
            return
        }
        let s: MandelbrotViewState = self.state
        let x: u32 = invocation.global.x
        let y: u32 = invocation.global.y
        let index: u32 = (y << 8) | x
        let px: i32 = to_i32(from_i32(__bitcast<u32, i32>(x)) * s.camera.res / 256.0)
        let py: i32 = to_i32(from_i32(__bitcast<u32, i32>(y)) * s.camera.res / 256.0)
        let tap: ReprojectionTap = reproject_coarse_pixel(
            s,
            self.cache.load(index: 1),
            self.cache.load(index: 2),
            preview.history,
            px,
            py,
        )
        let cached: Color = if tap.use_full {
            sample_snapshot(self.snapshot_pixels, tap.sx, tap.sy, tap.old_res)
        } else {
            let scale: f32 = 256.0 / max(tap.old_res, 1.0)
            sample(self.initial_pixels, tap.sx * scale, tap.sy * scale)
        }
        let live_reusable: bool = if tap.reusable { !s.is_input_settled() } else { false }
        if live_reusable {
            self.pixels.store(index: index, value: cached)
        } else {
            let computed: OrbitProgress = self.preview_progress.load(index: index)
            let known_escaped: bool = computed.epoch == preview.epoch
                && computed.is_escaped()
                && !computed.is_glitched()
            let proven_interior: bool = computed.epoch == preview.epoch
                && !computed.is_escaped()
                && !computed.is_glitched()
                && preview.prefix_only == 0
                && computed.iteration >= preview.budget
            if known_escaped || proven_interior {
                let current: Color = unpack_lab(progress_color(computed))
                let result: Color = if tap.reusable {
                    blend(cached, current, progress(s.input_age(), 60.0, 300.0))
                } else {
                    current
                }
                self.pixels.store(index: index, value: result)
            } else if tap.reusable {
                self.pixels.store(index: index, value: cached)
            } else if preview.prefix_only == 0 && computed.is_glitched() {
                self.pixels.store(index: index, value: unpack_lab(interior()))
            } else {
                self.pixels.store(index: index, value: Color::default())
            }
        }
    }

    fn finish_preview(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        if self.cache.load(index: 0).preview_dirty == 0 {
            return
        }
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 1 || preview.step_target == 0 {
            return
        }
        let s: MandelbrotViewState = self.state
        let full: ViewCache = self.cache.load(index: 1)
        let initial: ViewCache = self.cache.load(index: 2)
        if !s.is_input_settled() && (full.completed == 1 || initial.completed == 1) {
            return
        }
        self.preview_cache.store(index: 0, value: preview.commit_step())
    }

    // Preserve the first settled preview before native refinement finishes.
    // Neither this image nor its camera metadata changes while input is live.
    fn cache_initial(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let c: ViewCache = self.cache.load(index: 0)
        let old: ViewCache = self.cache.load(index: 2)
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 0 || !ref_state.can_publish_initial(s, c.epoch, old.epoch) {
            return
        }
        let index: u32 = (invocation.global.y << 8) | invocation.global.x
        self.initial_pixels.store(
            index: index,
            value: self.pixels.load(index: index),
        )
    }

    fn publish_initial(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let c: ViewCache = self.cache.load(index: 0)
        let old: ViewCache = self.cache.load(index: 2)
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 0 || !ref_state.can_publish_initial(s, c.epoch, old.epoch) {
            return
        }
        self.cache.store(index: 2, value: c.as_published_initial())
    }

    fn blur_horizontal(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).blur_dirty == 0 {
            return
        }
        let sigma: f32 = self.reference.load(index: 0).blur_sigma(self.state)
        self.horizontal.store(
            index: (invocation.global.y << 8) | invocation.global.x,
            value: gaussian(
                self.pixels,
                invocation.global.x,
                invocation.global.y,
                sigma,
                false,
            ),
        )
    }

    fn blur_vertical(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).blur_dirty == 0 {
            return
        }
        let sigma: f32 = self.reference.load(index: 0).blur_sigma(self.state)
        self.blurred.store(
            index: (invocation.global.y << 8) | invocation.global.x,
            value: gaussian(
                self.horizontal,
                invocation.global.x,
                invocation.global.y,
                sigma,
                true,
            ),
        )
    }

    // Spatially interleaved phases cover the whole image, rather
    // than sweeping rectangles. Each orbit resumes its own saved recurrence.
    fn restore_oracle(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<16, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        if !s.is_input_settled() {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let history: ViewCache = self.cache.load(index: 1)
        let schedule: RefinementSchedule = RefinementSchedule::for_view(s.camera.zoom, s.camera.res)
        if history.completed == 0 || history.budget < schedule.limit {
            return
        }
        if !same_camera(history, c) {
            return
        }
        let pixel: CohortPixel = schedule.rect_pixel(
            c.cursor,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let saved: OrbitProgress = self.progress_pixels.load(index: index)
        if saved.is_presentable_in(c.epoch) {
            return
        }
        let deep: SampleOracle = self.snapshot_oracle.load(index: index)
        if !deep.is_usable() {
            return
        }
        let preserved: OrbitProgress = OrbitProgress::from_oracle(deep, c.epoch, s.clock)
        let base: u32 = progress_color(preserved)
        self.progress_pixels.store(index: index, value: preserved)
        self.native_pixels.store(index: index, value: base)
        let antialiased: u32 = if history.aa == s.antialias {
            self.snapshot_pixels.load(index: index)
        } else {
            base
        }
        self.antialiased_pixels.store(index: index, value: antialiased)
    }

    // A sparse, full-depth lattice reveals real results while the denser
    // checkpoints are still iterating. It shares their persistent buffers.
    fn seed_refinement(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<16, 16, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        if c.cursor >= 16 || c.completed == 1 {
            return
        }
        let lane: u32 = (invocation.global.y % 4) * 4 + invocation.global.x % 4
        let rank: u32 = c.cursor * 16 + lane
        let block: PackedReference = self.orbit.load(index: 16390 + (rank >> 5))
        let pixel: CohortPixel = seed_pixel(
            block,
            rank,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let old: OrbitProgress = self.progress_pixels.load(index: index)
        if old.is_presentable_in(c.epoch) {
            return
        }
        let saved: OrbitProgress = if old.epoch == c.epoch {
            old
        } else {
            empty_progress(c.epoch)
        }
        let limit: u32 = iteration_limit(s.camera.zoom)
        let next: OrbitProgress = continue_pixel(
            self.orbit,
            ref_state.active * 8195,
            s.camera,
            pixel.sample(),
            limit,
            limit,
            saved,
        )
        self.progress_pixels.store(
            index: index,
            value: next.with_fade_start(s.clock),
        )
        let bits: u32 = progress_color(next)
        self.native_pixels.store(index: index, value: bits)
        self.antialiased_pixels.store(index: index, value: bits)
    }

    fn refine_pixels(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<16, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let schedule: RefinementSchedule = RefinementSchedule::for_view(s.camera.zoom, s.camera.res)
        let pixel: CohortPixel = schedule.rect_pixel(
            c.cursor,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let old: OrbitProgress = self.progress_pixels.load(index: index)
        let saved: OrbitProgress = if old.epoch == c.epoch {
            old
        } else {
            empty_progress(c.epoch)
        }
        if saved.is_terminal(schedule.limit) {
            return
        }
        let next: OrbitProgress = continue_pixel(
            self.orbit,
            ref_state.active * 8195,
            s.camera,
            pixel.sample(),
            schedule.limit,
            2048,
            saved,
        )
        // Once terminal, z_re is free to hold the pixel's fade start time.
        let stored: OrbitProgress = if next.is_terminal(schedule.limit) {
            next.with_fade_start(s.clock)
        } else {
            next
        }
        self.progress_pixels.store(index: index, value: stored)
        let bits: u32 = progress_color(next)
        self.native_pixels.store(index: index, value: bits)
        self.antialiased_pixels.store(index: index, value: bits)
    }

    fn antialias_pixels(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let schedule: RefinementSchedule = RefinementSchedule::for_view(s.camera.zoom, s.camera.res)
        let pixel: CohortPixel = schedule.aa_pixel(
            c.cursor,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let bits: u32 = self.native_pixels.load(index: index)
        let center: Color = unpack_lab(bits)
        let (left_i, right_i, up_i, down_i) = pixel.pixel.clamped_neighbor_indices(s.camera.res)
        let edge: f32 = max(
            max(
                contrast(center, unpack_lab(self.native_pixels.load(index: left_i))),
                contrast(center, unpack_lab(self.native_pixels.load(index: right_i))),
            ),
            max(
                contrast(center, unpack_lab(self.native_pixels.load(index: up_i))),
                contrast(center, unpack_lab(self.native_pixels.load(index: down_i))),
            ),
        )
        if s.antialias >= 0.5 && edge > 0.12 {
            let camera: Camera = s.camera
            let base: u32 = ref_state.active * 8195
            let a: Color = unpack_lab(sample_pixel(
                self.orbit,
                base,
                camera,
                pixel.offset_sample(Vec2 { x: 0.28, y: -0.28 }),
                schedule.limit,
            ))
            let b: Color = unpack_lab(sample_pixel(
                self.orbit,
                base,
                camera,
                pixel.offset_sample(Vec2 { x: -0.28, y: 0.28 }),
                schedule.limit,
            ))
            let averaged: Color = ((center + a) + b) / 3.0
            self.antialiased_pixels.store(
                index: index,
                value: pack_lab(averaged),
            )
        }
    }

    fn finish_refinement(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let end: u32 = RefinementSchedule::for_view(s.camera.zoom, s.camera.res).total_steps()
        if c.cursor >= end {
            return
        }
        self.cache.store(index: 0, value: c.advance_cursor(end))
    }

    fn cache_snapshot(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let c: ViewCache = self.cache.load(index: 0)
        let snapshot: ViewCache = self.cache.load(index: 1)
        if c.completed == 0 || snapshot.epoch == c.epoch {
            return
        }
        // Copy only on publication. Small dispatch also makes the idle guard
        // cheap; coalesced lanes cover the fixed-stride image in 64 strips.
        let lane: u32 = (invocation.global.y << 8) | invocation.global.x
        let mut strip: u32 = 0
        while strip < 64 {
            let index: u32 = lane + (strip << 16)
            let pixel: Pixel = Pixel {
                x: index & 2047,
                y: index >> 11,
            }
            if pixel.in_extent(s.camera.res) {
                self.snapshot_pixels.store(
                    index: index,
                    value: self.antialiased_pixels.load(index: index),
                )
                let result: OrbitProgress = self.progress_pixels.load(index: index)
                self.snapshot_oracle.store(index: index, value: result.to_oracle())
            }
            strip = strip + 1
        }
    }

    fn publish_snapshot(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let c: ViewCache = self.cache.load(index: 0)
        if c.completed == 1 {
            self.cache.store(index: 1, value: c)
        }
    }

    fn display_preview(self, px: i32, py: i32) -> i32 uses (FragmentSurface) {
        let s: MandelbrotViewState = self.state
        let pixel: Pixel = Pixel {
            x: __bitcast<i32, u32>(px) & 2047,
            y: __bitcast<i32, u32>(py) & 2047,
        }
        let index: u32 = pixel.native_index()
        let c: ViewCache = self.cache.load(index: 0)
        let reference_state: ReferenceControl = self.reference.load(index: 0)
        let reveal: f32 = sharpness(reference_state.display_age(s))
        let saved: OrbitProgress = self.progress_pixels.load(index: index)
        if saved.is_presentable_in(c.epoch) {
            let bits: u32 = self.antialiased_pixels.load(index: index)
            let amount: f32 = progress(s.clock - saved.fade_started_at(), 0.0, 350.0) * reveal
            if amount >= 1.0 {
                return display_rgba(unpack_lab(bits))
            }
            let coarse: Color = sample(
                self.blurred,
                from_i32(px) * 256.0 / s.camera.res,
                from_i32(py) * 256.0 / s.camera.res,
            )
            return display_rgba(blend(coarse, unpack_lab(bits), amount))
        }
        let coarse: Color = sample(
            self.blurred,
            from_i32(px) * 256.0 / s.camera.res,
            from_i32(py) * 256.0 / s.camera.res,
        )
        let stride: f32 = from_i32(to_i32((s.camera.res + 511.0) / 512.0))
        let tap: BilinearTap = lattice_tap(px, py, stride, s.camera.res - 1.0)
        let a: OrbitProgress = self.progress_pixels.load(index: tap.i00)
        let b: OrbitProgress = self.progress_pixels.load(index: tap.i10)
        let d: OrbitProgress = self.progress_pixels.load(index: tap.i01)
        let e: OrbitProgress = self.progress_pixels.load(index: tap.i11)
        let ready: bool = a.is_presentable_in(c.epoch)
            && b.is_presentable_in(c.epoch)
            && d.is_presentable_in(c.epoch)
            && e.is_presentable_in(c.epoch)
        if ready {
            let sparse: Color = blend_corners(
                unpack_lab(self.native_pixels.load(index: tap.i00)),
                unpack_lab(self.native_pixels.load(index: tap.i10)),
                unpack_lab(self.native_pixels.load(index: tap.i01)),
                unpack_lab(self.native_pixels.load(index: tap.i11)),
                tap.tx,
                tap.ty,
            )
            let latest_fade: f32 = finite_max(
                finite_max(a.fade_started_at(), b.fade_started_at()),
                finite_max(d.fade_started_at(), e.fade_started_at()),
            )
            let since: f32 = s.clock - latest_fade
            display_rgba(blend(coarse, sparse, progress(since, 0.0, 350.0) * reveal))
        } else {
            display_rgba(coarse)
        }
    }

    fn sync_url(self, event: own SurfaceLocationEvent) -> SurfaceStateEnvelope
        uses (SurfaceLocationTransition)
    {
        SurfaceStateEnvelope { state: sync_url_state(self.state, event) }
    }

    fn contact(self, event: own SurfaceContactEvent) -> SurfaceStateEnvelope
        uses (SurfaceContactTransition)
    {
        SurfaceStateEnvelope { state: contact_transition(self.state, event) }
    }

    fn navigate(self, event: own SurfaceEvent) -> SurfaceStateEnvelope
        uses (SurfaceTransition, SurfaceScheduling<ContinuousFrames>)
    {
        SurfaceStateEnvelope {
            state: transition(self.state, event),
        }
    }
}

reference_words: actor SmoothPerturbationalMandelbrot uses (
    GpuProgram<WebGpuBackend>,
    SurfaceQuality<SharpBacking>,
    SurfaceRecovery<StandardSurfaceRecovery>,
) {
    orbit: StorageBuffer<PackedReference, ORBIT_CAPACITY>,
    pixels: StorageBuffer<Color, 65536>,
    initial_pixels: StorageBuffer<Color, 65536>,
    preview_progress: StorageBuffer<OrbitProgress, 65536>,
    preview_cache: StorageBuffer<PreviewCache, 1>,
    snapshot_oracle: StorageBuffer<SampleOracle, 4194304>,
    horizontal: StorageBuffer<Color, 65536>,
    blurred: StorageBuffer<Color, 65536>,
    cache: StorageBuffer<ViewCache, 3>,
    anchor: StorageBuffer<ReferenceAnchor, 2>,
    reference: StorageBuffer<ReferenceControl, 1>,
    reference_words: StorageBuffer<u32, 16>,
    native_pixels: StorageBuffer<u32, 4194304>,
    antialiased_pixels: StorageBuffer<u32, 4194304>,
    progress_pixels: StorageBuffer<OrbitProgress, 4194304>,
    snapshot_pixels: StorageBuffer<u32, 4194304>,
    state: MandelbrotViewState,

    fn initial() -> SurfaceStateEnvelope uses (core::actor::InitialState) {
        initial_state()
    }

    const fn view() -> Surface<MandelbrotParams> {
        Surface {
            extent: Extent::square(2048),
            params: mandelbrot_params(),
        }
    }

    fn initialize_order(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let r: ReferenceControl = self.reference.load(index: 0)
        if r.active_valid == 1 || r.pending == 1 {
            return
        }
        self.orbit.store(
            index: 16390 + invocation.global.x,
            value: order_block(invocation.global.x),
        )
    }

    // Validate a candidate against the latest view before doing more work.
    fn discard_stale_reference(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let control: ReferenceControl = self.reference.load(index: 0)
        if control.pending == 0 {
            return
        }
        let bank: u32 = if control.active == 0 { 1 } else { 0 }
        let candidate: ReferenceAnchor = self.anchor.load(index: bank)
        let delta: Complex<f32> = candidate.delta_from(s)
        if candidate.limit < iteration_limit(s.camera.zoom)
            || max(abs(delta.re), abs(delta.im)) > s.camera.zoom * 0.5
        {
            self.reference.store(index: 0, value: control.cancel_pending())
        }
    }

    fn build_reference(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let previous: ViewCache = self.cache.load(index: 0)
        let initial: ViewCache = self.cache.load(index: 2)
        let previous_preview: PreviewCache = self.preview_cache.load(index: 0)
        let age: f32 = s.input_age()
        let budget: u32 = preview_budget(s.camera.zoom)
        let control: ReferenceControl = self.reference.load(index: 0)
        let active_anchor: ReferenceAnchor = self.anchor.load(index: control.active)
        let delta: Complex<f32> = active_anchor.delta_from(s)
        let target: u32 = iteration_limit(s.camera.zoom)
        let reusable: bool = control.active_valid == 1
            && active_anchor.limit >= target
            && abs(delta.re) <= s.camera.zoom * 0.125
            && abs(delta.im) <= s.camera.zoom * 0.125
        // Keep the active orbit available while a replacement advances in
        // bounded exact-integer batches. Pointer input never queues behind
        // an entire multi-thousand-step reference recurrence.
        let keep_active: bool = if control.pending == 0 { reusable } else { false }
        let defer_rebuild: bool = if control.active_valid == 1 { age < 60.0 } else { false }
        let skip_build: bool = if keep_active { true } else { defer_rebuild }
        if skip_build {
            let preview_bank: u32 = control.preview_bank(s)
            let preview_anchor: ReferenceAnchor = self.anchor.load(index: preview_bank)
            let next_preview: PreviewCache = previous_preview.sync_with_view(
                s,
                control,
                preview_anchor.generation,
                budget,
            )
            self.preview_cache.store(index: 0, value: next_preview)
            self.cache.store(
                index: 0,
                value: previous.sync_for_frame(s, control, next_preview, initial),
            )
        } else {
            let bank: u32 = 1 - control.active
            let base: u32 = bank * 8195
            let existing_pending: ReferenceAnchor = self.anchor.load(index: bank)
            let next_gen: u32 = (if active_anchor.generation > existing_pending.generation {
                active_anchor.generation
            } else {
                existing_pending.generation
            }) + 1
            let pending_anchor: ReferenceAnchor = if control.pending == 0 {
                let created: ReferenceAnchor = ReferenceAnchor::from_state(s, target, next_gen)
                self.anchor.store(index: bank, value: created)
                clear_reference_checkpoint(self.reference_words)
                self.orbit.store(index: base, value: PackedReference::zero())
                created
            } else {
                existing_pending
            }
            let center: Complex<ReferenceReal> = reference_center(pending_anchor)
            let mut z: Complex<ReferenceReal> = if control.pending == 0 {
                Complex::default()
            } else {
                load_reference_checkpoint(self.reference_words, control)
            }
            let mut i: u32 = if control.pending == 0 { 0 } else { control.index }
            let mut step: u32 = 0
            let mut escaped: bool = false
            while step < 64 && i < pending_anchor.limit && !escaped {
                let result: ReferenceStep = reference_step(z, center)
                escaped = result.escaped
                if !escaped {
                    z = result.value
                    self.orbit.store(
                        index: base + i + 1,
                        value: PackedReference::from_fixed(z),
                    )
                    i = i + 1
                }
                step = step + 1
            }
            self.orbit.store(
                index: base + ORBIT_CENTER_INDEX,
                value: PackedReference::from_fixed(center),
            )
            self.orbit.store(
                index: base + ORBIT_META_INDEX,
                value: PackedReference::from_metadata(i + 1, pending_anchor.limit),
            )
            let published: bool = escaped || i >= pending_anchor.limit
            let next_control: ReferenceControl = if published {
                ReferenceControl::publish(bank, i, z.re.sign, z.im.sign, s.clock)
            } else {
                store_reference_checkpoint(self.reference_words, z)
                control.advance_pending(i, z.re.sign, z.im.sign)
            }
            self.reference.store(index: 0, value: next_control)
            // Checkpoints belong to the orbit actually selected for preview.
            // During live input that can still be the active bank while its
            // replacement is being built in the other bank.
            let preview_bank: u32 = next_control.preview_bank(s)
            let preview_anchor: ReferenceAnchor = self.anchor.load(index: preview_bank)
            let next_preview: PreviewCache = previous_preview.sync_with_view(
                s,
                next_control,
                preview_anchor.generation,
                budget,
            )
            self.preview_cache.store(index: 0, value: next_preview)
            let synced_view: ViewCache = previous.sync_for_frame(
                s,
                next_control,
                next_preview,
                initial,
            )
            let next_view: ViewCache = if published {
                synced_view.invalidate_for_new_reference()
            } else {
                synced_view
            }
            self.cache.store(index: 0, value: next_view)
        }
        // Integer center differences are camera work, not per-pixel work.
        // Refresh both live banks after building/publishing the reference.
        let current = self.reference.load(index: 0)
        let full = self.cache.load(index: 1)
        let initial = self.cache.load(index: 2)
        let history = HistoryOffsets::for_view(s, full, initial)
        let mut preview = self.preview_cache.load(index: 0)
        preview.history = history
        self.preview_cache.store(index: 0, value: preview)
        let mut bank: u32 = 0
        while bank < 2 {
            let active = current.active_valid == 1 && bank == current.active
            let pending = current.pending == 1 && bank == 1 - current.active
            if active || pending {
                let offset = self.anchor.load(index: bank).delta_from(s)
                let index = bank * 8195 + ORBIT_META_INDEX
                let metadata = self.orbit.load(index: index)
                self.orbit.store(index: index, value: metadata.with_center_offset(offset))
            }
            bank = bank + 1
        }
    }

    fn advance_preview(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).preview_dirty == 0 {
            return
        }
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 1 || preview.step_target == 0 {
            return
        }
        let s: MandelbrotViewState = self.state
        let x: u32 = invocation.global.x
        let y: u32 = invocation.global.y
        let px: i32 = to_i32(from_i32(__bitcast<u32, i32>(x)) * s.camera.res / 256.0)
        let py: i32 = to_i32(from_i32(__bitcast<u32, i32>(y)) * s.camera.res / 256.0)
        if !s.is_input_settled() {
            let tap: ReprojectionTap = reproject_coarse_pixel(
                s,
                self.cache.load(index: 1),
                self.cache.load(index: 2),
                preview.history,
                px,
                py,
            )
            if tap.reusable {
                return
            }
        }
        let index: u32 = (y << 8) | x
        let old: OrbitProgress = self.preview_progress.load(index: index)
        let saved: OrbitProgress = if old.epoch == preview.epoch {
            old
        } else {
            empty_progress(preview.epoch)
        }
        let done_for_chunk: bool = if saved.is_terminal(preview.budget) {
            true
        } else {
            saved.iteration >= preview.step_target
        }
        if done_for_chunk {
            if old.epoch != preview.epoch {
                self.preview_progress.store(index: index, value: saved)
            }
        } else {
            let next: OrbitProgress = continue_preview_pixel(
                self.orbit,
                preview.reference_bank * 8195,
                s.camera,
                PixelSample::ordered_2x2(px, py),
                preview.step_target,
                preview.step_target,
                preview.prefix_only == 1,
                saved,
            )
            self.preview_progress.store(index: index, value: next)
        }
    }

    fn render_preview(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).preview_dirty == 0 {
            return
        }
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.step_target == 0 {
            return
        }
        let s: MandelbrotViewState = self.state
        let x: u32 = invocation.global.x
        let y: u32 = invocation.global.y
        let index: u32 = (y << 8) | x
        let px: i32 = to_i32(from_i32(__bitcast<u32, i32>(x)) * s.camera.res / 256.0)
        let py: i32 = to_i32(from_i32(__bitcast<u32, i32>(y)) * s.camera.res / 256.0)
        let tap: ReprojectionTap = reproject_coarse_pixel(
            s,
            self.cache.load(index: 1),
            self.cache.load(index: 2),
            preview.history,
            px,
            py,
        )
        let cached: Color = if tap.use_full {
            sample_snapshot(self.snapshot_pixels, tap.sx, tap.sy, tap.old_res)
        } else {
            let scale: f32 = 256.0 / max(tap.old_res, 1.0)
            sample(self.initial_pixels, tap.sx * scale, tap.sy * scale)
        }
        let live_reusable: bool = if tap.reusable { !s.is_input_settled() } else { false }
        if live_reusable {
            self.pixels.store(index: index, value: cached)
        } else {
            let computed: OrbitProgress = self.preview_progress.load(index: index)
            let known_escaped: bool = computed.epoch == preview.epoch
                && computed.is_escaped()
                && !computed.is_glitched()
            let proven_interior: bool = computed.epoch == preview.epoch
                && !computed.is_escaped()
                && !computed.is_glitched()
                && preview.prefix_only == 0
                && computed.iteration >= preview.budget
            if known_escaped || proven_interior {
                let current: Color = unpack_lab(progress_color(computed))
                let result: Color = if tap.reusable {
                    blend(cached, current, progress(s.input_age(), 60.0, 300.0))
                } else {
                    current
                }
                self.pixels.store(index: index, value: result)
            } else if tap.reusable {
                self.pixels.store(index: index, value: cached)
            } else if preview.prefix_only == 0 && computed.is_glitched() {
                self.pixels.store(index: index, value: unpack_lab(interior()))
            } else {
                self.pixels.store(index: index, value: Color::default())
            }
        }
    }

    fn finish_preview(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        if self.cache.load(index: 0).preview_dirty == 0 {
            return
        }
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 1 || preview.step_target == 0 {
            return
        }
        let s: MandelbrotViewState = self.state
        let full: ViewCache = self.cache.load(index: 1)
        let initial: ViewCache = self.cache.load(index: 2)
        if !s.is_input_settled() && (full.completed == 1 || initial.completed == 1) {
            return
        }
        self.preview_cache.store(index: 0, value: preview.commit_step())
    }

    // Preserve the first settled preview before native refinement finishes.
    // Neither this image nor its camera metadata changes while input is live.
    fn cache_initial(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let c: ViewCache = self.cache.load(index: 0)
        let old: ViewCache = self.cache.load(index: 2)
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 0 || !ref_state.can_publish_initial(s, c.epoch, old.epoch) {
            return
        }
        let index: u32 = (invocation.global.y << 8) | invocation.global.x
        self.initial_pixels.store(
            index: index,
            value: self.pixels.load(index: index),
        )
    }

    fn publish_initial(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let c: ViewCache = self.cache.load(index: 0)
        let old: ViewCache = self.cache.load(index: 2)
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 0 || !ref_state.can_publish_initial(s, c.epoch, old.epoch) {
            return
        }
        self.cache.store(index: 2, value: c.as_published_initial())
    }

    fn blur_horizontal(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).blur_dirty == 0 {
            return
        }
        let sigma: f32 = self.reference.load(index: 0).blur_sigma(self.state)
        self.horizontal.store(
            index: (invocation.global.y << 8) | invocation.global.x,
            value: gaussian(
                self.pixels,
                invocation.global.x,
                invocation.global.y,
                sigma,
                false,
            ),
        )
    }

    fn blur_vertical(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).blur_dirty == 0 {
            return
        }
        let sigma: f32 = self.reference.load(index: 0).blur_sigma(self.state)
        self.blurred.store(
            index: (invocation.global.y << 8) | invocation.global.x,
            value: gaussian(
                self.horizontal,
                invocation.global.x,
                invocation.global.y,
                sigma,
                true,
            ),
        )
    }

    // Spatially interleaved phases cover the whole image, rather
    // than sweeping rectangles. Each orbit resumes its own saved recurrence.
    fn restore_oracle(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<16, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        if !s.is_input_settled() {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let history: ViewCache = self.cache.load(index: 1)
        let schedule: RefinementSchedule = RefinementSchedule::for_view(s.camera.zoom, s.camera.res)
        if history.completed == 0 || history.budget < schedule.limit {
            return
        }
        if !same_camera(history, c) {
            return
        }
        let pixel: CohortPixel = schedule.rect_pixel(
            c.cursor,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let saved: OrbitProgress = self.progress_pixels.load(index: index)
        if saved.is_presentable_in(c.epoch) {
            return
        }
        let deep: SampleOracle = self.snapshot_oracle.load(index: index)
        if !deep.is_usable() {
            return
        }
        let preserved: OrbitProgress = OrbitProgress::from_oracle(deep, c.epoch, s.clock)
        let base: u32 = progress_color(preserved)
        self.progress_pixels.store(index: index, value: preserved)
        self.native_pixels.store(index: index, value: base)
        let antialiased: u32 = if history.aa == s.antialias {
            self.snapshot_pixels.load(index: index)
        } else {
            base
        }
        self.antialiased_pixels.store(index: index, value: antialiased)
    }

    // A sparse, full-depth lattice reveals real results while the denser
    // checkpoints are still iterating. It shares their persistent buffers.
    fn seed_refinement(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<16, 16, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        if c.cursor >= 16 || c.completed == 1 {
            return
        }
        let lane: u32 = (invocation.global.y % 4) * 4 + invocation.global.x % 4
        let rank: u32 = c.cursor * 16 + lane
        let block: PackedReference = self.orbit.load(index: 16390 + (rank >> 5))
        let pixel: CohortPixel = seed_pixel(
            block,
            rank,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let old: OrbitProgress = self.progress_pixels.load(index: index)
        if old.is_presentable_in(c.epoch) {
            return
        }
        let saved: OrbitProgress = if old.epoch == c.epoch {
            old
        } else {
            empty_progress(c.epoch)
        }
        let limit: u32 = iteration_limit(s.camera.zoom)
        let next: OrbitProgress = continue_pixel(
            self.orbit,
            ref_state.active * 8195,
            s.camera,
            pixel.sample(),
            limit,
            limit,
            saved,
        )
        self.progress_pixels.store(
            index: index,
            value: next.with_fade_start(s.clock),
        )
        let bits: u32 = progress_color(next)
        self.native_pixels.store(index: index, value: bits)
        self.antialiased_pixels.store(index: index, value: bits)
    }

    fn refine_pixels(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<16, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let schedule: RefinementSchedule = RefinementSchedule::for_view(s.camera.zoom, s.camera.res)
        let pixel: CohortPixel = schedule.rect_pixel(
            c.cursor,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let old: OrbitProgress = self.progress_pixels.load(index: index)
        let saved: OrbitProgress = if old.epoch == c.epoch {
            old
        } else {
            empty_progress(c.epoch)
        }
        if saved.is_terminal(schedule.limit) {
            return
        }
        let next: OrbitProgress = continue_pixel(
            self.orbit,
            ref_state.active * 8195,
            s.camera,
            pixel.sample(),
            schedule.limit,
            2048,
            saved,
        )
        // Once terminal, z_re is free to hold the pixel's fade start time.
        let stored: OrbitProgress = if next.is_terminal(schedule.limit) {
            next.with_fade_start(s.clock)
        } else {
            next
        }
        self.progress_pixels.store(index: index, value: stored)
        let bits: u32 = progress_color(next)
        self.native_pixels.store(index: index, value: bits)
        self.antialiased_pixels.store(index: index, value: bits)
    }

    fn antialias_pixels(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let schedule: RefinementSchedule = RefinementSchedule::for_view(s.camera.zoom, s.camera.res)
        let pixel: CohortPixel = schedule.aa_pixel(
            c.cursor,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let bits: u32 = self.native_pixels.load(index: index)
        let center: Color = unpack_lab(bits)
        let (left_i, right_i, up_i, down_i) = pixel.pixel.clamped_neighbor_indices(s.camera.res)
        let edge: f32 = max(
            max(
                contrast(center, unpack_lab(self.native_pixels.load(index: left_i))),
                contrast(center, unpack_lab(self.native_pixels.load(index: right_i))),
            ),
            max(
                contrast(center, unpack_lab(self.native_pixels.load(index: up_i))),
                contrast(center, unpack_lab(self.native_pixels.load(index: down_i))),
            ),
        )
        if s.antialias >= 0.5 && edge > 0.12 {
            let camera: Camera = s.camera
            let base: u32 = ref_state.active * 8195
            let a: Color = unpack_lab(sample_pixel(
                self.orbit,
                base,
                camera,
                pixel.offset_sample(Vec2 { x: 0.28, y: -0.28 }),
                schedule.limit,
            ))
            let b: Color = unpack_lab(sample_pixel(
                self.orbit,
                base,
                camera,
                pixel.offset_sample(Vec2 { x: -0.28, y: 0.28 }),
                schedule.limit,
            ))
            let averaged: Color = ((center + a) + b) / 3.0
            self.antialiased_pixels.store(
                index: index,
                value: pack_lab(averaged),
            )
        }
    }

    fn finish_refinement(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let end: u32 = RefinementSchedule::for_view(s.camera.zoom, s.camera.res).total_steps()
        if c.cursor >= end {
            return
        }
        self.cache.store(index: 0, value: c.advance_cursor(end))
    }

    fn cache_snapshot(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let c: ViewCache = self.cache.load(index: 0)
        let snapshot: ViewCache = self.cache.load(index: 1)
        if c.completed == 0 || snapshot.epoch == c.epoch {
            return
        }
        // Copy only on publication. Small dispatch also makes the idle guard
        // cheap; coalesced lanes cover the fixed-stride image in 64 strips.
        let lane: u32 = (invocation.global.y << 8) | invocation.global.x
        let mut strip: u32 = 0
        while strip < 64 {
            let index: u32 = lane + (strip << 16)
            let pixel: Pixel = Pixel {
                x: index & 2047,
                y: index >> 11,
            }
            if pixel.in_extent(s.camera.res) {
                self.snapshot_pixels.store(
                    index: index,
                    value: self.antialiased_pixels.load(index: index),
                )
                let result: OrbitProgress = self.progress_pixels.load(index: index)
                self.snapshot_oracle.store(index: index, value: result.to_oracle())
            }
            strip = strip + 1
        }
    }

    fn publish_snapshot(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let c: ViewCache = self.cache.load(index: 0)
        if c.completed == 1 {
            self.cache.store(index: 1, value: c)
        }
    }

    fn display_preview(self, px: i32, py: i32) -> i32 uses (FragmentSurface) {
        let s: MandelbrotViewState = self.state
        let pixel: Pixel = Pixel {
            x: __bitcast<i32, u32>(px) & 2047,
            y: __bitcast<i32, u32>(py) & 2047,
        }
        let index: u32 = pixel.native_index()
        let c: ViewCache = self.cache.load(index: 0)
        let reference_state: ReferenceControl = self.reference.load(index: 0)
        let reveal: f32 = sharpness(reference_state.display_age(s))
        let saved: OrbitProgress = self.progress_pixels.load(index: index)
        if saved.is_presentable_in(c.epoch) {
            let bits: u32 = self.antialiased_pixels.load(index: index)
            let amount: f32 = progress(s.clock - saved.fade_started_at(), 0.0, 350.0) * reveal
            if amount >= 1.0 {
                return display_rgba(unpack_lab(bits))
            }
            let coarse: Color = sample(
                self.blurred,
                from_i32(px) * 256.0 / s.camera.res,
                from_i32(py) * 256.0 / s.camera.res,
            )
            return display_rgba(blend(coarse, unpack_lab(bits), amount))
        }
        let coarse: Color = sample(
            self.blurred,
            from_i32(px) * 256.0 / s.camera.res,
            from_i32(py) * 256.0 / s.camera.res,
        )
        let stride: f32 = from_i32(to_i32((s.camera.res + 511.0) / 512.0))
        let tap: BilinearTap = lattice_tap(px, py, stride, s.camera.res - 1.0)
        let a: OrbitProgress = self.progress_pixels.load(index: tap.i00)
        let b: OrbitProgress = self.progress_pixels.load(index: tap.i10)
        let d: OrbitProgress = self.progress_pixels.load(index: tap.i01)
        let e: OrbitProgress = self.progress_pixels.load(index: tap.i11)
        let ready: bool = a.is_presentable_in(c.epoch)
            && b.is_presentable_in(c.epoch)
            && d.is_presentable_in(c.epoch)
            && e.is_presentable_in(c.epoch)
        if ready {
            let sparse: Color = blend_corners(
                unpack_lab(self.native_pixels.load(index: tap.i00)),
                unpack_lab(self.native_pixels.load(index: tap.i10)),
                unpack_lab(self.native_pixels.load(index: tap.i01)),
                unpack_lab(self.native_pixels.load(index: tap.i11)),
                tap.tx,
                tap.ty,
            )
            let latest_fade: f32 = finite_max(
                finite_max(a.fade_started_at(), b.fade_started_at()),
                finite_max(d.fade_started_at(), e.fade_started_at()),
            )
            let since: f32 = s.clock - latest_fade
            display_rgba(blend(coarse, sparse, progress(since, 0.0, 350.0) * reveal))
        } else {
            display_rgba(coarse)
        }
    }

    fn sync_url(self, event: own SurfaceLocationEvent) -> SurfaceStateEnvelope
        uses (SurfaceLocationTransition)
    {
        SurfaceStateEnvelope { state: sync_url_state(self.state, event) }
    }

    fn contact(self, event: own SurfaceContactEvent) -> SurfaceStateEnvelope
        uses (SurfaceContactTransition)
    {
        SurfaceStateEnvelope { state: contact_transition(self.state, event) }
    }

    fn navigate(self, event: own SurfaceEvent) -> SurfaceStateEnvelope
        uses (SurfaceTransition, SurfaceScheduling<ContinuousFrames>)
    {
        SurfaceStateEnvelope {
            state: transition(self.state, event),
        }
    }
}

native_pixels: actor SmoothPerturbationalMandelbrot uses (
    GpuProgram<WebGpuBackend>,
    SurfaceQuality<SharpBacking>,
    SurfaceRecovery<StandardSurfaceRecovery>,
) {
    orbit: StorageBuffer<PackedReference, ORBIT_CAPACITY>,
    pixels: StorageBuffer<Color, 65536>,
    initial_pixels: StorageBuffer<Color, 65536>,
    preview_progress: StorageBuffer<OrbitProgress, 65536>,
    preview_cache: StorageBuffer<PreviewCache, 1>,
    snapshot_oracle: StorageBuffer<SampleOracle, 4194304>,
    horizontal: StorageBuffer<Color, 65536>,
    blurred: StorageBuffer<Color, 65536>,
    cache: StorageBuffer<ViewCache, 3>,
    anchor: StorageBuffer<ReferenceAnchor, 2>,
    reference: StorageBuffer<ReferenceControl, 1>,
    reference_words: StorageBuffer<u32, 16>,
    native_pixels: StorageBuffer<u32, 4194304>,
    antialiased_pixels: StorageBuffer<u32, 4194304>,
    progress_pixels: StorageBuffer<OrbitProgress, 4194304>,
    snapshot_pixels: StorageBuffer<u32, 4194304>,
    state: MandelbrotViewState,

    fn initial() -> SurfaceStateEnvelope uses (core::actor::InitialState) {
        initial_state()
    }

    const fn view() -> Surface<MandelbrotParams> {
        Surface {
            extent: Extent::square(2048),
            params: mandelbrot_params(),
        }
    }

    fn initialize_order(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let r: ReferenceControl = self.reference.load(index: 0)
        if r.active_valid == 1 || r.pending == 1 {
            return
        }
        self.orbit.store(
            index: 16390 + invocation.global.x,
            value: order_block(invocation.global.x),
        )
    }

    // Validate a candidate against the latest view before doing more work.
    fn discard_stale_reference(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let control: ReferenceControl = self.reference.load(index: 0)
        if control.pending == 0 {
            return
        }
        let bank: u32 = if control.active == 0 { 1 } else { 0 }
        let candidate: ReferenceAnchor = self.anchor.load(index: bank)
        let delta: Complex<f32> = candidate.delta_from(s)
        if candidate.limit < iteration_limit(s.camera.zoom)
            || max(abs(delta.re), abs(delta.im)) > s.camera.zoom * 0.5
        {
            self.reference.store(index: 0, value: control.cancel_pending())
        }
    }

    fn build_reference(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let previous: ViewCache = self.cache.load(index: 0)
        let initial: ViewCache = self.cache.load(index: 2)
        let previous_preview: PreviewCache = self.preview_cache.load(index: 0)
        let age: f32 = s.input_age()
        let budget: u32 = preview_budget(s.camera.zoom)
        let control: ReferenceControl = self.reference.load(index: 0)
        let active_anchor: ReferenceAnchor = self.anchor.load(index: control.active)
        let delta: Complex<f32> = active_anchor.delta_from(s)
        let target: u32 = iteration_limit(s.camera.zoom)
        let reusable: bool = control.active_valid == 1
            && active_anchor.limit >= target
            && abs(delta.re) <= s.camera.zoom * 0.125
            && abs(delta.im) <= s.camera.zoom * 0.125
        // Keep the active orbit available while a replacement advances in
        // bounded exact-integer batches. Pointer input never queues behind
        // an entire multi-thousand-step reference recurrence.
        let keep_active: bool = if control.pending == 0 { reusable } else { false }
        let defer_rebuild: bool = if control.active_valid == 1 { age < 60.0 } else { false }
        let skip_build: bool = if keep_active { true } else { defer_rebuild }
        if skip_build {
            let preview_bank: u32 = control.preview_bank(s)
            let preview_anchor: ReferenceAnchor = self.anchor.load(index: preview_bank)
            let next_preview: PreviewCache = previous_preview.sync_with_view(
                s,
                control,
                preview_anchor.generation,
                budget,
            )
            self.preview_cache.store(index: 0, value: next_preview)
            self.cache.store(
                index: 0,
                value: previous.sync_for_frame(s, control, next_preview, initial),
            )
        } else {
            let bank: u32 = 1 - control.active
            let base: u32 = bank * 8195
            let existing_pending: ReferenceAnchor = self.anchor.load(index: bank)
            let next_gen: u32 = (if active_anchor.generation > existing_pending.generation {
                active_anchor.generation
            } else {
                existing_pending.generation
            }) + 1
            let pending_anchor: ReferenceAnchor = if control.pending == 0 {
                let created: ReferenceAnchor = ReferenceAnchor::from_state(s, target, next_gen)
                self.anchor.store(index: bank, value: created)
                clear_reference_checkpoint(self.reference_words)
                self.orbit.store(index: base, value: PackedReference::zero())
                created
            } else {
                existing_pending
            }
            let center: Complex<ReferenceReal> = reference_center(pending_anchor)
            let mut z: Complex<ReferenceReal> = if control.pending == 0 {
                Complex::default()
            } else {
                load_reference_checkpoint(self.reference_words, control)
            }
            let mut i: u32 = if control.pending == 0 { 0 } else { control.index }
            let mut step: u32 = 0
            let mut escaped: bool = false
            while step < 64 && i < pending_anchor.limit && !escaped {
                let result: ReferenceStep = reference_step(z, center)
                escaped = result.escaped
                if !escaped {
                    z = result.value
                    self.orbit.store(
                        index: base + i + 1,
                        value: PackedReference::from_fixed(z),
                    )
                    i = i + 1
                }
                step = step + 1
            }
            self.orbit.store(
                index: base + ORBIT_CENTER_INDEX,
                value: PackedReference::from_fixed(center),
            )
            self.orbit.store(
                index: base + ORBIT_META_INDEX,
                value: PackedReference::from_metadata(i + 1, pending_anchor.limit),
            )
            let published: bool = escaped || i >= pending_anchor.limit
            let next_control: ReferenceControl = if published {
                ReferenceControl::publish(bank, i, z.re.sign, z.im.sign, s.clock)
            } else {
                store_reference_checkpoint(self.reference_words, z)
                control.advance_pending(i, z.re.sign, z.im.sign)
            }
            self.reference.store(index: 0, value: next_control)
            // Checkpoints belong to the orbit actually selected for preview.
            // During live input that can still be the active bank while its
            // replacement is being built in the other bank.
            let preview_bank: u32 = next_control.preview_bank(s)
            let preview_anchor: ReferenceAnchor = self.anchor.load(index: preview_bank)
            let next_preview: PreviewCache = previous_preview.sync_with_view(
                s,
                next_control,
                preview_anchor.generation,
                budget,
            )
            self.preview_cache.store(index: 0, value: next_preview)
            let synced_view: ViewCache = previous.sync_for_frame(
                s,
                next_control,
                next_preview,
                initial,
            )
            let next_view: ViewCache = if published {
                synced_view.invalidate_for_new_reference()
            } else {
                synced_view
            }
            self.cache.store(index: 0, value: next_view)
        }
        // Integer center differences are camera work, not per-pixel work.
        // Refresh both live banks after building/publishing the reference.
        let current = self.reference.load(index: 0)
        let full = self.cache.load(index: 1)
        let initial = self.cache.load(index: 2)
        let history = HistoryOffsets::for_view(s, full, initial)
        let mut preview = self.preview_cache.load(index: 0)
        preview.history = history
        self.preview_cache.store(index: 0, value: preview)
        let mut bank: u32 = 0
        while bank < 2 {
            let active = current.active_valid == 1 && bank == current.active
            let pending = current.pending == 1 && bank == 1 - current.active
            if active || pending {
                let offset = self.anchor.load(index: bank).delta_from(s)
                let index = bank * 8195 + ORBIT_META_INDEX
                let metadata = self.orbit.load(index: index)
                self.orbit.store(index: index, value: metadata.with_center_offset(offset))
            }
            bank = bank + 1
        }
    }

    fn advance_preview(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).preview_dirty == 0 {
            return
        }
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 1 || preview.step_target == 0 {
            return
        }
        let s: MandelbrotViewState = self.state
        let x: u32 = invocation.global.x
        let y: u32 = invocation.global.y
        let px: i32 = to_i32(from_i32(__bitcast<u32, i32>(x)) * s.camera.res / 256.0)
        let py: i32 = to_i32(from_i32(__bitcast<u32, i32>(y)) * s.camera.res / 256.0)
        if !s.is_input_settled() {
            let tap: ReprojectionTap = reproject_coarse_pixel(
                s,
                self.cache.load(index: 1),
                self.cache.load(index: 2),
                preview.history,
                px,
                py,
            )
            if tap.reusable {
                return
            }
        }
        let index: u32 = (y << 8) | x
        let old: OrbitProgress = self.preview_progress.load(index: index)
        let saved: OrbitProgress = if old.epoch == preview.epoch {
            old
        } else {
            empty_progress(preview.epoch)
        }
        let done_for_chunk: bool = if saved.is_terminal(preview.budget) {
            true
        } else {
            saved.iteration >= preview.step_target
        }
        if done_for_chunk {
            if old.epoch != preview.epoch {
                self.preview_progress.store(index: index, value: saved)
            }
        } else {
            let next: OrbitProgress = continue_preview_pixel(
                self.orbit,
                preview.reference_bank * 8195,
                s.camera,
                PixelSample::ordered_2x2(px, py),
                preview.step_target,
                preview.step_target,
                preview.prefix_only == 1,
                saved,
            )
            self.preview_progress.store(index: index, value: next)
        }
    }

    fn render_preview(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).preview_dirty == 0 {
            return
        }
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.step_target == 0 {
            return
        }
        let s: MandelbrotViewState = self.state
        let x: u32 = invocation.global.x
        let y: u32 = invocation.global.y
        let index: u32 = (y << 8) | x
        let px: i32 = to_i32(from_i32(__bitcast<u32, i32>(x)) * s.camera.res / 256.0)
        let py: i32 = to_i32(from_i32(__bitcast<u32, i32>(y)) * s.camera.res / 256.0)
        let tap: ReprojectionTap = reproject_coarse_pixel(
            s,
            self.cache.load(index: 1),
            self.cache.load(index: 2),
            preview.history,
            px,
            py,
        )
        let cached: Color = if tap.use_full {
            sample_snapshot(self.snapshot_pixels, tap.sx, tap.sy, tap.old_res)
        } else {
            let scale: f32 = 256.0 / max(tap.old_res, 1.0)
            sample(self.initial_pixels, tap.sx * scale, tap.sy * scale)
        }
        let live_reusable: bool = if tap.reusable { !s.is_input_settled() } else { false }
        if live_reusable {
            self.pixels.store(index: index, value: cached)
        } else {
            let computed: OrbitProgress = self.preview_progress.load(index: index)
            let known_escaped: bool = computed.epoch == preview.epoch
                && computed.is_escaped()
                && !computed.is_glitched()
            let proven_interior: bool = computed.epoch == preview.epoch
                && !computed.is_escaped()
                && !computed.is_glitched()
                && preview.prefix_only == 0
                && computed.iteration >= preview.budget
            if known_escaped || proven_interior {
                let current: Color = unpack_lab(progress_color(computed))
                let result: Color = if tap.reusable {
                    blend(cached, current, progress(s.input_age(), 60.0, 300.0))
                } else {
                    current
                }
                self.pixels.store(index: index, value: result)
            } else if tap.reusable {
                self.pixels.store(index: index, value: cached)
            } else if preview.prefix_only == 0 && computed.is_glitched() {
                self.pixels.store(index: index, value: unpack_lab(interior()))
            } else {
                self.pixels.store(index: index, value: Color::default())
            }
        }
    }

    fn finish_preview(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        if self.cache.load(index: 0).preview_dirty == 0 {
            return
        }
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 1 || preview.step_target == 0 {
            return
        }
        let s: MandelbrotViewState = self.state
        let full: ViewCache = self.cache.load(index: 1)
        let initial: ViewCache = self.cache.load(index: 2)
        if !s.is_input_settled() && (full.completed == 1 || initial.completed == 1) {
            return
        }
        self.preview_cache.store(index: 0, value: preview.commit_step())
    }

    // Preserve the first settled preview before native refinement finishes.
    // Neither this image nor its camera metadata changes while input is live.
    fn cache_initial(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let c: ViewCache = self.cache.load(index: 0)
        let old: ViewCache = self.cache.load(index: 2)
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 0 || !ref_state.can_publish_initial(s, c.epoch, old.epoch) {
            return
        }
        let index: u32 = (invocation.global.y << 8) | invocation.global.x
        self.initial_pixels.store(
            index: index,
            value: self.pixels.load(index: index),
        )
    }

    fn publish_initial(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let c: ViewCache = self.cache.load(index: 0)
        let old: ViewCache = self.cache.load(index: 2)
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 0 || !ref_state.can_publish_initial(s, c.epoch, old.epoch) {
            return
        }
        self.cache.store(index: 2, value: c.as_published_initial())
    }

    fn blur_horizontal(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).blur_dirty == 0 {
            return
        }
        let sigma: f32 = self.reference.load(index: 0).blur_sigma(self.state)
        self.horizontal.store(
            index: (invocation.global.y << 8) | invocation.global.x,
            value: gaussian(
                self.pixels,
                invocation.global.x,
                invocation.global.y,
                sigma,
                false,
            ),
        )
    }

    fn blur_vertical(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).blur_dirty == 0 {
            return
        }
        let sigma: f32 = self.reference.load(index: 0).blur_sigma(self.state)
        self.blurred.store(
            index: (invocation.global.y << 8) | invocation.global.x,
            value: gaussian(
                self.horizontal,
                invocation.global.x,
                invocation.global.y,
                sigma,
                true,
            ),
        )
    }

    // Spatially interleaved phases cover the whole image, rather
    // than sweeping rectangles. Each orbit resumes its own saved recurrence.
    fn restore_oracle(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<16, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        if !s.is_input_settled() {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let history: ViewCache = self.cache.load(index: 1)
        let schedule: RefinementSchedule = RefinementSchedule::for_view(s.camera.zoom, s.camera.res)
        if history.completed == 0 || history.budget < schedule.limit {
            return
        }
        if !same_camera(history, c) {
            return
        }
        let pixel: CohortPixel = schedule.rect_pixel(
            c.cursor,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let saved: OrbitProgress = self.progress_pixels.load(index: index)
        if saved.is_presentable_in(c.epoch) {
            return
        }
        let deep: SampleOracle = self.snapshot_oracle.load(index: index)
        if !deep.is_usable() {
            return
        }
        let preserved: OrbitProgress = OrbitProgress::from_oracle(deep, c.epoch, s.clock)
        let base: u32 = progress_color(preserved)
        self.progress_pixels.store(index: index, value: preserved)
        self.native_pixels.store(index: index, value: base)
        let antialiased: u32 = if history.aa == s.antialias {
            self.snapshot_pixels.load(index: index)
        } else {
            base
        }
        self.antialiased_pixels.store(index: index, value: antialiased)
    }

    // A sparse, full-depth lattice reveals real results while the denser
    // checkpoints are still iterating. It shares their persistent buffers.
    fn seed_refinement(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<16, 16, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        if c.cursor >= 16 || c.completed == 1 {
            return
        }
        let lane: u32 = (invocation.global.y % 4) * 4 + invocation.global.x % 4
        let rank: u32 = c.cursor * 16 + lane
        let block: PackedReference = self.orbit.load(index: 16390 + (rank >> 5))
        let pixel: CohortPixel = seed_pixel(
            block,
            rank,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let old: OrbitProgress = self.progress_pixels.load(index: index)
        if old.is_presentable_in(c.epoch) {
            return
        }
        let saved: OrbitProgress = if old.epoch == c.epoch {
            old
        } else {
            empty_progress(c.epoch)
        }
        let limit: u32 = iteration_limit(s.camera.zoom)
        let next: OrbitProgress = continue_pixel(
            self.orbit,
            ref_state.active * 8195,
            s.camera,
            pixel.sample(),
            limit,
            limit,
            saved,
        )
        self.progress_pixels.store(
            index: index,
            value: next.with_fade_start(s.clock),
        )
        let bits: u32 = progress_color(next)
        self.native_pixels.store(index: index, value: bits)
        self.antialiased_pixels.store(index: index, value: bits)
    }

    fn refine_pixels(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<16, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let schedule: RefinementSchedule = RefinementSchedule::for_view(s.camera.zoom, s.camera.res)
        let pixel: CohortPixel = schedule.rect_pixel(
            c.cursor,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let old: OrbitProgress = self.progress_pixels.load(index: index)
        let saved: OrbitProgress = if old.epoch == c.epoch {
            old
        } else {
            empty_progress(c.epoch)
        }
        if saved.is_terminal(schedule.limit) {
            return
        }
        let next: OrbitProgress = continue_pixel(
            self.orbit,
            ref_state.active * 8195,
            s.camera,
            pixel.sample(),
            schedule.limit,
            2048,
            saved,
        )
        // Once terminal, z_re is free to hold the pixel's fade start time.
        let stored: OrbitProgress = if next.is_terminal(schedule.limit) {
            next.with_fade_start(s.clock)
        } else {
            next
        }
        self.progress_pixels.store(index: index, value: stored)
        let bits: u32 = progress_color(next)
        self.native_pixels.store(index: index, value: bits)
        self.antialiased_pixels.store(index: index, value: bits)
    }

    fn antialias_pixels(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let schedule: RefinementSchedule = RefinementSchedule::for_view(s.camera.zoom, s.camera.res)
        let pixel: CohortPixel = schedule.aa_pixel(
            c.cursor,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let bits: u32 = self.native_pixels.load(index: index)
        let center: Color = unpack_lab(bits)
        let (left_i, right_i, up_i, down_i) = pixel.pixel.clamped_neighbor_indices(s.camera.res)
        let edge: f32 = max(
            max(
                contrast(center, unpack_lab(self.native_pixels.load(index: left_i))),
                contrast(center, unpack_lab(self.native_pixels.load(index: right_i))),
            ),
            max(
                contrast(center, unpack_lab(self.native_pixels.load(index: up_i))),
                contrast(center, unpack_lab(self.native_pixels.load(index: down_i))),
            ),
        )
        if s.antialias >= 0.5 && edge > 0.12 {
            let camera: Camera = s.camera
            let base: u32 = ref_state.active * 8195
            let a: Color = unpack_lab(sample_pixel(
                self.orbit,
                base,
                camera,
                pixel.offset_sample(Vec2 { x: 0.28, y: -0.28 }),
                schedule.limit,
            ))
            let b: Color = unpack_lab(sample_pixel(
                self.orbit,
                base,
                camera,
                pixel.offset_sample(Vec2 { x: -0.28, y: 0.28 }),
                schedule.limit,
            ))
            let averaged: Color = ((center + a) + b) / 3.0
            self.antialiased_pixels.store(
                index: index,
                value: pack_lab(averaged),
            )
        }
    }

    fn finish_refinement(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let end: u32 = RefinementSchedule::for_view(s.camera.zoom, s.camera.res).total_steps()
        if c.cursor >= end {
            return
        }
        self.cache.store(index: 0, value: c.advance_cursor(end))
    }

    fn cache_snapshot(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let c: ViewCache = self.cache.load(index: 0)
        let snapshot: ViewCache = self.cache.load(index: 1)
        if c.completed == 0 || snapshot.epoch == c.epoch {
            return
        }
        // Copy only on publication. Small dispatch also makes the idle guard
        // cheap; coalesced lanes cover the fixed-stride image in 64 strips.
        let lane: u32 = (invocation.global.y << 8) | invocation.global.x
        let mut strip: u32 = 0
        while strip < 64 {
            let index: u32 = lane + (strip << 16)
            let pixel: Pixel = Pixel {
                x: index & 2047,
                y: index >> 11,
            }
            if pixel.in_extent(s.camera.res) {
                self.snapshot_pixels.store(
                    index: index,
                    value: self.antialiased_pixels.load(index: index),
                )
                let result: OrbitProgress = self.progress_pixels.load(index: index)
                self.snapshot_oracle.store(index: index, value: result.to_oracle())
            }
            strip = strip + 1
        }
    }

    fn publish_snapshot(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let c: ViewCache = self.cache.load(index: 0)
        if c.completed == 1 {
            self.cache.store(index: 1, value: c)
        }
    }

    fn display_preview(self, px: i32, py: i32) -> i32 uses (FragmentSurface) {
        let s: MandelbrotViewState = self.state
        let pixel: Pixel = Pixel {
            x: __bitcast<i32, u32>(px) & 2047,
            y: __bitcast<i32, u32>(py) & 2047,
        }
        let index: u32 = pixel.native_index()
        let c: ViewCache = self.cache.load(index: 0)
        let reference_state: ReferenceControl = self.reference.load(index: 0)
        let reveal: f32 = sharpness(reference_state.display_age(s))
        let saved: OrbitProgress = self.progress_pixels.load(index: index)
        if saved.is_presentable_in(c.epoch) {
            let bits: u32 = self.antialiased_pixels.load(index: index)
            let amount: f32 = progress(s.clock - saved.fade_started_at(), 0.0, 350.0) * reveal
            if amount >= 1.0 {
                return display_rgba(unpack_lab(bits))
            }
            let coarse: Color = sample(
                self.blurred,
                from_i32(px) * 256.0 / s.camera.res,
                from_i32(py) * 256.0 / s.camera.res,
            )
            return display_rgba(blend(coarse, unpack_lab(bits), amount))
        }
        let coarse: Color = sample(
            self.blurred,
            from_i32(px) * 256.0 / s.camera.res,
            from_i32(py) * 256.0 / s.camera.res,
        )
        let stride: f32 = from_i32(to_i32((s.camera.res + 511.0) / 512.0))
        let tap: BilinearTap = lattice_tap(px, py, stride, s.camera.res - 1.0)
        let a: OrbitProgress = self.progress_pixels.load(index: tap.i00)
        let b: OrbitProgress = self.progress_pixels.load(index: tap.i10)
        let d: OrbitProgress = self.progress_pixels.load(index: tap.i01)
        let e: OrbitProgress = self.progress_pixels.load(index: tap.i11)
        let ready: bool = a.is_presentable_in(c.epoch)
            && b.is_presentable_in(c.epoch)
            && d.is_presentable_in(c.epoch)
            && e.is_presentable_in(c.epoch)
        if ready {
            let sparse: Color = blend_corners(
                unpack_lab(self.native_pixels.load(index: tap.i00)),
                unpack_lab(self.native_pixels.load(index: tap.i10)),
                unpack_lab(self.native_pixels.load(index: tap.i01)),
                unpack_lab(self.native_pixels.load(index: tap.i11)),
                tap.tx,
                tap.ty,
            )
            let latest_fade: f32 = finite_max(
                finite_max(a.fade_started_at(), b.fade_started_at()),
                finite_max(d.fade_started_at(), e.fade_started_at()),
            )
            let since: f32 = s.clock - latest_fade
            display_rgba(blend(coarse, sparse, progress(since, 0.0, 350.0) * reveal))
        } else {
            display_rgba(coarse)
        }
    }

    fn sync_url(self, event: own SurfaceLocationEvent) -> SurfaceStateEnvelope
        uses (SurfaceLocationTransition)
    {
        SurfaceStateEnvelope { state: sync_url_state(self.state, event) }
    }

    fn contact(self, event: own SurfaceContactEvent) -> SurfaceStateEnvelope
        uses (SurfaceContactTransition)
    {
        SurfaceStateEnvelope { state: contact_transition(self.state, event) }
    }

    fn navigate(self, event: own SurfaceEvent) -> SurfaceStateEnvelope
        uses (SurfaceTransition, SurfaceScheduling<ContinuousFrames>)
    {
        SurfaceStateEnvelope {
            state: transition(self.state, event),
        }
    }
}

antialiased_pixels: actor SmoothPerturbationalMandelbrot uses (
    GpuProgram<WebGpuBackend>,
    SurfaceQuality<SharpBacking>,
    SurfaceRecovery<StandardSurfaceRecovery>,
) {
    orbit: StorageBuffer<PackedReference, ORBIT_CAPACITY>,
    pixels: StorageBuffer<Color, 65536>,
    initial_pixels: StorageBuffer<Color, 65536>,
    preview_progress: StorageBuffer<OrbitProgress, 65536>,
    preview_cache: StorageBuffer<PreviewCache, 1>,
    snapshot_oracle: StorageBuffer<SampleOracle, 4194304>,
    horizontal: StorageBuffer<Color, 65536>,
    blurred: StorageBuffer<Color, 65536>,
    cache: StorageBuffer<ViewCache, 3>,
    anchor: StorageBuffer<ReferenceAnchor, 2>,
    reference: StorageBuffer<ReferenceControl, 1>,
    reference_words: StorageBuffer<u32, 16>,
    native_pixels: StorageBuffer<u32, 4194304>,
    antialiased_pixels: StorageBuffer<u32, 4194304>,
    progress_pixels: StorageBuffer<OrbitProgress, 4194304>,
    snapshot_pixels: StorageBuffer<u32, 4194304>,
    state: MandelbrotViewState,

    fn initial() -> SurfaceStateEnvelope uses (core::actor::InitialState) {
        initial_state()
    }

    const fn view() -> Surface<MandelbrotParams> {
        Surface {
            extent: Extent::square(2048),
            params: mandelbrot_params(),
        }
    }

    fn initialize_order(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let r: ReferenceControl = self.reference.load(index: 0)
        if r.active_valid == 1 || r.pending == 1 {
            return
        }
        self.orbit.store(
            index: 16390 + invocation.global.x,
            value: order_block(invocation.global.x),
        )
    }

    // Validate a candidate against the latest view before doing more work.
    fn discard_stale_reference(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let control: ReferenceControl = self.reference.load(index: 0)
        if control.pending == 0 {
            return
        }
        let bank: u32 = if control.active == 0 { 1 } else { 0 }
        let candidate: ReferenceAnchor = self.anchor.load(index: bank)
        let delta: Complex<f32> = candidate.delta_from(s)
        if candidate.limit < iteration_limit(s.camera.zoom)
            || max(abs(delta.re), abs(delta.im)) > s.camera.zoom * 0.5
        {
            self.reference.store(index: 0, value: control.cancel_pending())
        }
    }

    fn build_reference(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let previous: ViewCache = self.cache.load(index: 0)
        let initial: ViewCache = self.cache.load(index: 2)
        let previous_preview: PreviewCache = self.preview_cache.load(index: 0)
        let age: f32 = s.input_age()
        let budget: u32 = preview_budget(s.camera.zoom)
        let control: ReferenceControl = self.reference.load(index: 0)
        let active_anchor: ReferenceAnchor = self.anchor.load(index: control.active)
        let delta: Complex<f32> = active_anchor.delta_from(s)
        let target: u32 = iteration_limit(s.camera.zoom)
        let reusable: bool = control.active_valid == 1
            && active_anchor.limit >= target
            && abs(delta.re) <= s.camera.zoom * 0.125
            && abs(delta.im) <= s.camera.zoom * 0.125
        // Keep the active orbit available while a replacement advances in
        // bounded exact-integer batches. Pointer input never queues behind
        // an entire multi-thousand-step reference recurrence.
        let keep_active: bool = if control.pending == 0 { reusable } else { false }
        let defer_rebuild: bool = if control.active_valid == 1 { age < 60.0 } else { false }
        let skip_build: bool = if keep_active { true } else { defer_rebuild }
        if skip_build {
            let preview_bank: u32 = control.preview_bank(s)
            let preview_anchor: ReferenceAnchor = self.anchor.load(index: preview_bank)
            let next_preview: PreviewCache = previous_preview.sync_with_view(
                s,
                control,
                preview_anchor.generation,
                budget,
            )
            self.preview_cache.store(index: 0, value: next_preview)
            self.cache.store(
                index: 0,
                value: previous.sync_for_frame(s, control, next_preview, initial),
            )
        } else {
            let bank: u32 = 1 - control.active
            let base: u32 = bank * 8195
            let existing_pending: ReferenceAnchor = self.anchor.load(index: bank)
            let next_gen: u32 = (if active_anchor.generation > existing_pending.generation {
                active_anchor.generation
            } else {
                existing_pending.generation
            }) + 1
            let pending_anchor: ReferenceAnchor = if control.pending == 0 {
                let created: ReferenceAnchor = ReferenceAnchor::from_state(s, target, next_gen)
                self.anchor.store(index: bank, value: created)
                clear_reference_checkpoint(self.reference_words)
                self.orbit.store(index: base, value: PackedReference::zero())
                created
            } else {
                existing_pending
            }
            let center: Complex<ReferenceReal> = reference_center(pending_anchor)
            let mut z: Complex<ReferenceReal> = if control.pending == 0 {
                Complex::default()
            } else {
                load_reference_checkpoint(self.reference_words, control)
            }
            let mut i: u32 = if control.pending == 0 { 0 } else { control.index }
            let mut step: u32 = 0
            let mut escaped: bool = false
            while step < 64 && i < pending_anchor.limit && !escaped {
                let result: ReferenceStep = reference_step(z, center)
                escaped = result.escaped
                if !escaped {
                    z = result.value
                    self.orbit.store(
                        index: base + i + 1,
                        value: PackedReference::from_fixed(z),
                    )
                    i = i + 1
                }
                step = step + 1
            }
            self.orbit.store(
                index: base + ORBIT_CENTER_INDEX,
                value: PackedReference::from_fixed(center),
            )
            self.orbit.store(
                index: base + ORBIT_META_INDEX,
                value: PackedReference::from_metadata(i + 1, pending_anchor.limit),
            )
            let published: bool = escaped || i >= pending_anchor.limit
            let next_control: ReferenceControl = if published {
                ReferenceControl::publish(bank, i, z.re.sign, z.im.sign, s.clock)
            } else {
                store_reference_checkpoint(self.reference_words, z)
                control.advance_pending(i, z.re.sign, z.im.sign)
            }
            self.reference.store(index: 0, value: next_control)
            // Checkpoints belong to the orbit actually selected for preview.
            // During live input that can still be the active bank while its
            // replacement is being built in the other bank.
            let preview_bank: u32 = next_control.preview_bank(s)
            let preview_anchor: ReferenceAnchor = self.anchor.load(index: preview_bank)
            let next_preview: PreviewCache = previous_preview.sync_with_view(
                s,
                next_control,
                preview_anchor.generation,
                budget,
            )
            self.preview_cache.store(index: 0, value: next_preview)
            let synced_view: ViewCache = previous.sync_for_frame(
                s,
                next_control,
                next_preview,
                initial,
            )
            let next_view: ViewCache = if published {
                synced_view.invalidate_for_new_reference()
            } else {
                synced_view
            }
            self.cache.store(index: 0, value: next_view)
        }
        // Integer center differences are camera work, not per-pixel work.
        // Refresh both live banks after building/publishing the reference.
        let current = self.reference.load(index: 0)
        let full = self.cache.load(index: 1)
        let initial = self.cache.load(index: 2)
        let history = HistoryOffsets::for_view(s, full, initial)
        let mut preview = self.preview_cache.load(index: 0)
        preview.history = history
        self.preview_cache.store(index: 0, value: preview)
        let mut bank: u32 = 0
        while bank < 2 {
            let active = current.active_valid == 1 && bank == current.active
            let pending = current.pending == 1 && bank == 1 - current.active
            if active || pending {
                let offset = self.anchor.load(index: bank).delta_from(s)
                let index = bank * 8195 + ORBIT_META_INDEX
                let metadata = self.orbit.load(index: index)
                self.orbit.store(index: index, value: metadata.with_center_offset(offset))
            }
            bank = bank + 1
        }
    }

    fn advance_preview(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).preview_dirty == 0 {
            return
        }
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 1 || preview.step_target == 0 {
            return
        }
        let s: MandelbrotViewState = self.state
        let x: u32 = invocation.global.x
        let y: u32 = invocation.global.y
        let px: i32 = to_i32(from_i32(__bitcast<u32, i32>(x)) * s.camera.res / 256.0)
        let py: i32 = to_i32(from_i32(__bitcast<u32, i32>(y)) * s.camera.res / 256.0)
        if !s.is_input_settled() {
            let tap: ReprojectionTap = reproject_coarse_pixel(
                s,
                self.cache.load(index: 1),
                self.cache.load(index: 2),
                preview.history,
                px,
                py,
            )
            if tap.reusable {
                return
            }
        }
        let index: u32 = (y << 8) | x
        let old: OrbitProgress = self.preview_progress.load(index: index)
        let saved: OrbitProgress = if old.epoch == preview.epoch {
            old
        } else {
            empty_progress(preview.epoch)
        }
        let done_for_chunk: bool = if saved.is_terminal(preview.budget) {
            true
        } else {
            saved.iteration >= preview.step_target
        }
        if done_for_chunk {
            if old.epoch != preview.epoch {
                self.preview_progress.store(index: index, value: saved)
            }
        } else {
            let next: OrbitProgress = continue_preview_pixel(
                self.orbit,
                preview.reference_bank * 8195,
                s.camera,
                PixelSample::ordered_2x2(px, py),
                preview.step_target,
                preview.step_target,
                preview.prefix_only == 1,
                saved,
            )
            self.preview_progress.store(index: index, value: next)
        }
    }

    fn render_preview(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).preview_dirty == 0 {
            return
        }
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.step_target == 0 {
            return
        }
        let s: MandelbrotViewState = self.state
        let x: u32 = invocation.global.x
        let y: u32 = invocation.global.y
        let index: u32 = (y << 8) | x
        let px: i32 = to_i32(from_i32(__bitcast<u32, i32>(x)) * s.camera.res / 256.0)
        let py: i32 = to_i32(from_i32(__bitcast<u32, i32>(y)) * s.camera.res / 256.0)
        let tap: ReprojectionTap = reproject_coarse_pixel(
            s,
            self.cache.load(index: 1),
            self.cache.load(index: 2),
            preview.history,
            px,
            py,
        )
        let cached: Color = if tap.use_full {
            sample_snapshot(self.snapshot_pixels, tap.sx, tap.sy, tap.old_res)
        } else {
            let scale: f32 = 256.0 / max(tap.old_res, 1.0)
            sample(self.initial_pixels, tap.sx * scale, tap.sy * scale)
        }
        let live_reusable: bool = if tap.reusable { !s.is_input_settled() } else { false }
        if live_reusable {
            self.pixels.store(index: index, value: cached)
        } else {
            let computed: OrbitProgress = self.preview_progress.load(index: index)
            let known_escaped: bool = computed.epoch == preview.epoch
                && computed.is_escaped()
                && !computed.is_glitched()
            let proven_interior: bool = computed.epoch == preview.epoch
                && !computed.is_escaped()
                && !computed.is_glitched()
                && preview.prefix_only == 0
                && computed.iteration >= preview.budget
            if known_escaped || proven_interior {
                let current: Color = unpack_lab(progress_color(computed))
                let result: Color = if tap.reusable {
                    blend(cached, current, progress(s.input_age(), 60.0, 300.0))
                } else {
                    current
                }
                self.pixels.store(index: index, value: result)
            } else if tap.reusable {
                self.pixels.store(index: index, value: cached)
            } else if preview.prefix_only == 0 && computed.is_glitched() {
                self.pixels.store(index: index, value: unpack_lab(interior()))
            } else {
                self.pixels.store(index: index, value: Color::default())
            }
        }
    }

    fn finish_preview(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        if self.cache.load(index: 0).preview_dirty == 0 {
            return
        }
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 1 || preview.step_target == 0 {
            return
        }
        let s: MandelbrotViewState = self.state
        let full: ViewCache = self.cache.load(index: 1)
        let initial: ViewCache = self.cache.load(index: 2)
        if !s.is_input_settled() && (full.completed == 1 || initial.completed == 1) {
            return
        }
        self.preview_cache.store(index: 0, value: preview.commit_step())
    }

    // Preserve the first settled preview before native refinement finishes.
    // Neither this image nor its camera metadata changes while input is live.
    fn cache_initial(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let c: ViewCache = self.cache.load(index: 0)
        let old: ViewCache = self.cache.load(index: 2)
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 0 || !ref_state.can_publish_initial(s, c.epoch, old.epoch) {
            return
        }
        let index: u32 = (invocation.global.y << 8) | invocation.global.x
        self.initial_pixels.store(
            index: index,
            value: self.pixels.load(index: index),
        )
    }

    fn publish_initial(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let c: ViewCache = self.cache.load(index: 0)
        let old: ViewCache = self.cache.load(index: 2)
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 0 || !ref_state.can_publish_initial(s, c.epoch, old.epoch) {
            return
        }
        self.cache.store(index: 2, value: c.as_published_initial())
    }

    fn blur_horizontal(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).blur_dirty == 0 {
            return
        }
        let sigma: f32 = self.reference.load(index: 0).blur_sigma(self.state)
        self.horizontal.store(
            index: (invocation.global.y << 8) | invocation.global.x,
            value: gaussian(
                self.pixels,
                invocation.global.x,
                invocation.global.y,
                sigma,
                false,
            ),
        )
    }

    fn blur_vertical(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).blur_dirty == 0 {
            return
        }
        let sigma: f32 = self.reference.load(index: 0).blur_sigma(self.state)
        self.blurred.store(
            index: (invocation.global.y << 8) | invocation.global.x,
            value: gaussian(
                self.horizontal,
                invocation.global.x,
                invocation.global.y,
                sigma,
                true,
            ),
        )
    }

    // Spatially interleaved phases cover the whole image, rather
    // than sweeping rectangles. Each orbit resumes its own saved recurrence.
    fn restore_oracle(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<16, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        if !s.is_input_settled() {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let history: ViewCache = self.cache.load(index: 1)
        let schedule: RefinementSchedule = RefinementSchedule::for_view(s.camera.zoom, s.camera.res)
        if history.completed == 0 || history.budget < schedule.limit {
            return
        }
        if !same_camera(history, c) {
            return
        }
        let pixel: CohortPixel = schedule.rect_pixel(
            c.cursor,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let saved: OrbitProgress = self.progress_pixels.load(index: index)
        if saved.is_presentable_in(c.epoch) {
            return
        }
        let deep: SampleOracle = self.snapshot_oracle.load(index: index)
        if !deep.is_usable() {
            return
        }
        let preserved: OrbitProgress = OrbitProgress::from_oracle(deep, c.epoch, s.clock)
        let base: u32 = progress_color(preserved)
        self.progress_pixels.store(index: index, value: preserved)
        self.native_pixels.store(index: index, value: base)
        let antialiased: u32 = if history.aa == s.antialias {
            self.snapshot_pixels.load(index: index)
        } else {
            base
        }
        self.antialiased_pixels.store(index: index, value: antialiased)
    }

    // A sparse, full-depth lattice reveals real results while the denser
    // checkpoints are still iterating. It shares their persistent buffers.
    fn seed_refinement(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<16, 16, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        if c.cursor >= 16 || c.completed == 1 {
            return
        }
        let lane: u32 = (invocation.global.y % 4) * 4 + invocation.global.x % 4
        let rank: u32 = c.cursor * 16 + lane
        let block: PackedReference = self.orbit.load(index: 16390 + (rank >> 5))
        let pixel: CohortPixel = seed_pixel(
            block,
            rank,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let old: OrbitProgress = self.progress_pixels.load(index: index)
        if old.is_presentable_in(c.epoch) {
            return
        }
        let saved: OrbitProgress = if old.epoch == c.epoch {
            old
        } else {
            empty_progress(c.epoch)
        }
        let limit: u32 = iteration_limit(s.camera.zoom)
        let next: OrbitProgress = continue_pixel(
            self.orbit,
            ref_state.active * 8195,
            s.camera,
            pixel.sample(),
            limit,
            limit,
            saved,
        )
        self.progress_pixels.store(
            index: index,
            value: next.with_fade_start(s.clock),
        )
        let bits: u32 = progress_color(next)
        self.native_pixels.store(index: index, value: bits)
        self.antialiased_pixels.store(index: index, value: bits)
    }

    fn refine_pixels(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<16, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let schedule: RefinementSchedule = RefinementSchedule::for_view(s.camera.zoom, s.camera.res)
        let pixel: CohortPixel = schedule.rect_pixel(
            c.cursor,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let old: OrbitProgress = self.progress_pixels.load(index: index)
        let saved: OrbitProgress = if old.epoch == c.epoch {
            old
        } else {
            empty_progress(c.epoch)
        }
        if saved.is_terminal(schedule.limit) {
            return
        }
        let next: OrbitProgress = continue_pixel(
            self.orbit,
            ref_state.active * 8195,
            s.camera,
            pixel.sample(),
            schedule.limit,
            2048,
            saved,
        )
        // Once terminal, z_re is free to hold the pixel's fade start time.
        let stored: OrbitProgress = if next.is_terminal(schedule.limit) {
            next.with_fade_start(s.clock)
        } else {
            next
        }
        self.progress_pixels.store(index: index, value: stored)
        let bits: u32 = progress_color(next)
        self.native_pixels.store(index: index, value: bits)
        self.antialiased_pixels.store(index: index, value: bits)
    }

    fn antialias_pixels(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let schedule: RefinementSchedule = RefinementSchedule::for_view(s.camera.zoom, s.camera.res)
        let pixel: CohortPixel = schedule.aa_pixel(
            c.cursor,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let bits: u32 = self.native_pixels.load(index: index)
        let center: Color = unpack_lab(bits)
        let (left_i, right_i, up_i, down_i) = pixel.pixel.clamped_neighbor_indices(s.camera.res)
        let edge: f32 = max(
            max(
                contrast(center, unpack_lab(self.native_pixels.load(index: left_i))),
                contrast(center, unpack_lab(self.native_pixels.load(index: right_i))),
            ),
            max(
                contrast(center, unpack_lab(self.native_pixels.load(index: up_i))),
                contrast(center, unpack_lab(self.native_pixels.load(index: down_i))),
            ),
        )
        if s.antialias >= 0.5 && edge > 0.12 {
            let camera: Camera = s.camera
            let base: u32 = ref_state.active * 8195
            let a: Color = unpack_lab(sample_pixel(
                self.orbit,
                base,
                camera,
                pixel.offset_sample(Vec2 { x: 0.28, y: -0.28 }),
                schedule.limit,
            ))
            let b: Color = unpack_lab(sample_pixel(
                self.orbit,
                base,
                camera,
                pixel.offset_sample(Vec2 { x: -0.28, y: 0.28 }),
                schedule.limit,
            ))
            let averaged: Color = ((center + a) + b) / 3.0
            self.antialiased_pixels.store(
                index: index,
                value: pack_lab(averaged),
            )
        }
    }

    fn finish_refinement(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let end: u32 = RefinementSchedule::for_view(s.camera.zoom, s.camera.res).total_steps()
        if c.cursor >= end {
            return
        }
        self.cache.store(index: 0, value: c.advance_cursor(end))
    }

    fn cache_snapshot(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let c: ViewCache = self.cache.load(index: 0)
        let snapshot: ViewCache = self.cache.load(index: 1)
        if c.completed == 0 || snapshot.epoch == c.epoch {
            return
        }
        // Copy only on publication. Small dispatch also makes the idle guard
        // cheap; coalesced lanes cover the fixed-stride image in 64 strips.
        let lane: u32 = (invocation.global.y << 8) | invocation.global.x
        let mut strip: u32 = 0
        while strip < 64 {
            let index: u32 = lane + (strip << 16)
            let pixel: Pixel = Pixel {
                x: index & 2047,
                y: index >> 11,
            }
            if pixel.in_extent(s.camera.res) {
                self.snapshot_pixels.store(
                    index: index,
                    value: self.antialiased_pixels.load(index: index),
                )
                let result: OrbitProgress = self.progress_pixels.load(index: index)
                self.snapshot_oracle.store(index: index, value: result.to_oracle())
            }
            strip = strip + 1
        }
    }

    fn publish_snapshot(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let c: ViewCache = self.cache.load(index: 0)
        if c.completed == 1 {
            self.cache.store(index: 1, value: c)
        }
    }

    fn display_preview(self, px: i32, py: i32) -> i32 uses (FragmentSurface) {
        let s: MandelbrotViewState = self.state
        let pixel: Pixel = Pixel {
            x: __bitcast<i32, u32>(px) & 2047,
            y: __bitcast<i32, u32>(py) & 2047,
        }
        let index: u32 = pixel.native_index()
        let c: ViewCache = self.cache.load(index: 0)
        let reference_state: ReferenceControl = self.reference.load(index: 0)
        let reveal: f32 = sharpness(reference_state.display_age(s))
        let saved: OrbitProgress = self.progress_pixels.load(index: index)
        if saved.is_presentable_in(c.epoch) {
            let bits: u32 = self.antialiased_pixels.load(index: index)
            let amount: f32 = progress(s.clock - saved.fade_started_at(), 0.0, 350.0) * reveal
            if amount >= 1.0 {
                return display_rgba(unpack_lab(bits))
            }
            let coarse: Color = sample(
                self.blurred,
                from_i32(px) * 256.0 / s.camera.res,
                from_i32(py) * 256.0 / s.camera.res,
            )
            return display_rgba(blend(coarse, unpack_lab(bits), amount))
        }
        let coarse: Color = sample(
            self.blurred,
            from_i32(px) * 256.0 / s.camera.res,
            from_i32(py) * 256.0 / s.camera.res,
        )
        let stride: f32 = from_i32(to_i32((s.camera.res + 511.0) / 512.0))
        let tap: BilinearTap = lattice_tap(px, py, stride, s.camera.res - 1.0)
        let a: OrbitProgress = self.progress_pixels.load(index: tap.i00)
        let b: OrbitProgress = self.progress_pixels.load(index: tap.i10)
        let d: OrbitProgress = self.progress_pixels.load(index: tap.i01)
        let e: OrbitProgress = self.progress_pixels.load(index: tap.i11)
        let ready: bool = a.is_presentable_in(c.epoch)
            && b.is_presentable_in(c.epoch)
            && d.is_presentable_in(c.epoch)
            && e.is_presentable_in(c.epoch)
        if ready {
            let sparse: Color = blend_corners(
                unpack_lab(self.native_pixels.load(index: tap.i00)),
                unpack_lab(self.native_pixels.load(index: tap.i10)),
                unpack_lab(self.native_pixels.load(index: tap.i01)),
                unpack_lab(self.native_pixels.load(index: tap.i11)),
                tap.tx,
                tap.ty,
            )
            let latest_fade: f32 = finite_max(
                finite_max(a.fade_started_at(), b.fade_started_at()),
                finite_max(d.fade_started_at(), e.fade_started_at()),
            )
            let since: f32 = s.clock - latest_fade
            display_rgba(blend(coarse, sparse, progress(since, 0.0, 350.0) * reveal))
        } else {
            display_rgba(coarse)
        }
    }

    fn sync_url(self, event: own SurfaceLocationEvent) -> SurfaceStateEnvelope
        uses (SurfaceLocationTransition)
    {
        SurfaceStateEnvelope { state: sync_url_state(self.state, event) }
    }

    fn contact(self, event: own SurfaceContactEvent) -> SurfaceStateEnvelope
        uses (SurfaceContactTransition)
    {
        SurfaceStateEnvelope { state: contact_transition(self.state, event) }
    }

    fn navigate(self, event: own SurfaceEvent) -> SurfaceStateEnvelope
        uses (SurfaceTransition, SurfaceScheduling<ContinuousFrames>)
    {
        SurfaceStateEnvelope {
            state: transition(self.state, event),
        }
    }
}

progress_pixels: actor SmoothPerturbationalMandelbrot uses (
    GpuProgram<WebGpuBackend>,
    SurfaceQuality<SharpBacking>,
    SurfaceRecovery<StandardSurfaceRecovery>,
) {
    orbit: StorageBuffer<PackedReference, ORBIT_CAPACITY>,
    pixels: StorageBuffer<Color, 65536>,
    initial_pixels: StorageBuffer<Color, 65536>,
    preview_progress: StorageBuffer<OrbitProgress, 65536>,
    preview_cache: StorageBuffer<PreviewCache, 1>,
    snapshot_oracle: StorageBuffer<SampleOracle, 4194304>,
    horizontal: StorageBuffer<Color, 65536>,
    blurred: StorageBuffer<Color, 65536>,
    cache: StorageBuffer<ViewCache, 3>,
    anchor: StorageBuffer<ReferenceAnchor, 2>,
    reference: StorageBuffer<ReferenceControl, 1>,
    reference_words: StorageBuffer<u32, 16>,
    native_pixels: StorageBuffer<u32, 4194304>,
    antialiased_pixels: StorageBuffer<u32, 4194304>,
    progress_pixels: StorageBuffer<OrbitProgress, 4194304>,
    snapshot_pixels: StorageBuffer<u32, 4194304>,
    state: MandelbrotViewState,

    fn initial() -> SurfaceStateEnvelope uses (core::actor::InitialState) {
        initial_state()
    }

    const fn view() -> Surface<MandelbrotParams> {
        Surface {
            extent: Extent::square(2048),
            params: mandelbrot_params(),
        }
    }

    fn initialize_order(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let r: ReferenceControl = self.reference.load(index: 0)
        if r.active_valid == 1 || r.pending == 1 {
            return
        }
        self.orbit.store(
            index: 16390 + invocation.global.x,
            value: order_block(invocation.global.x),
        )
    }

    // Validate a candidate against the latest view before doing more work.
    fn discard_stale_reference(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let control: ReferenceControl = self.reference.load(index: 0)
        if control.pending == 0 {
            return
        }
        let bank: u32 = if control.active == 0 { 1 } else { 0 }
        let candidate: ReferenceAnchor = self.anchor.load(index: bank)
        let delta: Complex<f32> = candidate.delta_from(s)
        if candidate.limit < iteration_limit(s.camera.zoom)
            || max(abs(delta.re), abs(delta.im)) > s.camera.zoom * 0.5
        {
            self.reference.store(index: 0, value: control.cancel_pending())
        }
    }

    fn build_reference(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let previous: ViewCache = self.cache.load(index: 0)
        let initial: ViewCache = self.cache.load(index: 2)
        let previous_preview: PreviewCache = self.preview_cache.load(index: 0)
        let age: f32 = s.input_age()
        let budget: u32 = preview_budget(s.camera.zoom)
        let control: ReferenceControl = self.reference.load(index: 0)
        let active_anchor: ReferenceAnchor = self.anchor.load(index: control.active)
        let delta: Complex<f32> = active_anchor.delta_from(s)
        let target: u32 = iteration_limit(s.camera.zoom)
        let reusable: bool = control.active_valid == 1
            && active_anchor.limit >= target
            && abs(delta.re) <= s.camera.zoom * 0.125
            && abs(delta.im) <= s.camera.zoom * 0.125
        // Keep the active orbit available while a replacement advances in
        // bounded exact-integer batches. Pointer input never queues behind
        // an entire multi-thousand-step reference recurrence.
        let keep_active: bool = if control.pending == 0 { reusable } else { false }
        let defer_rebuild: bool = if control.active_valid == 1 { age < 60.0 } else { false }
        let skip_build: bool = if keep_active { true } else { defer_rebuild }
        if skip_build {
            let preview_bank: u32 = control.preview_bank(s)
            let preview_anchor: ReferenceAnchor = self.anchor.load(index: preview_bank)
            let next_preview: PreviewCache = previous_preview.sync_with_view(
                s,
                control,
                preview_anchor.generation,
                budget,
            )
            self.preview_cache.store(index: 0, value: next_preview)
            self.cache.store(
                index: 0,
                value: previous.sync_for_frame(s, control, next_preview, initial),
            )
        } else {
            let bank: u32 = 1 - control.active
            let base: u32 = bank * 8195
            let existing_pending: ReferenceAnchor = self.anchor.load(index: bank)
            let next_gen: u32 = (if active_anchor.generation > existing_pending.generation {
                active_anchor.generation
            } else {
                existing_pending.generation
            }) + 1
            let pending_anchor: ReferenceAnchor = if control.pending == 0 {
                let created: ReferenceAnchor = ReferenceAnchor::from_state(s, target, next_gen)
                self.anchor.store(index: bank, value: created)
                clear_reference_checkpoint(self.reference_words)
                self.orbit.store(index: base, value: PackedReference::zero())
                created
            } else {
                existing_pending
            }
            let center: Complex<ReferenceReal> = reference_center(pending_anchor)
            let mut z: Complex<ReferenceReal> = if control.pending == 0 {
                Complex::default()
            } else {
                load_reference_checkpoint(self.reference_words, control)
            }
            let mut i: u32 = if control.pending == 0 { 0 } else { control.index }
            let mut step: u32 = 0
            let mut escaped: bool = false
            while step < 64 && i < pending_anchor.limit && !escaped {
                let result: ReferenceStep = reference_step(z, center)
                escaped = result.escaped
                if !escaped {
                    z = result.value
                    self.orbit.store(
                        index: base + i + 1,
                        value: PackedReference::from_fixed(z),
                    )
                    i = i + 1
                }
                step = step + 1
            }
            self.orbit.store(
                index: base + ORBIT_CENTER_INDEX,
                value: PackedReference::from_fixed(center),
            )
            self.orbit.store(
                index: base + ORBIT_META_INDEX,
                value: PackedReference::from_metadata(i + 1, pending_anchor.limit),
            )
            let published: bool = escaped || i >= pending_anchor.limit
            let next_control: ReferenceControl = if published {
                ReferenceControl::publish(bank, i, z.re.sign, z.im.sign, s.clock)
            } else {
                store_reference_checkpoint(self.reference_words, z)
                control.advance_pending(i, z.re.sign, z.im.sign)
            }
            self.reference.store(index: 0, value: next_control)
            // Checkpoints belong to the orbit actually selected for preview.
            // During live input that can still be the active bank while its
            // replacement is being built in the other bank.
            let preview_bank: u32 = next_control.preview_bank(s)
            let preview_anchor: ReferenceAnchor = self.anchor.load(index: preview_bank)
            let next_preview: PreviewCache = previous_preview.sync_with_view(
                s,
                next_control,
                preview_anchor.generation,
                budget,
            )
            self.preview_cache.store(index: 0, value: next_preview)
            let synced_view: ViewCache = previous.sync_for_frame(
                s,
                next_control,
                next_preview,
                initial,
            )
            let next_view: ViewCache = if published {
                synced_view.invalidate_for_new_reference()
            } else {
                synced_view
            }
            self.cache.store(index: 0, value: next_view)
        }
        // Integer center differences are camera work, not per-pixel work.
        // Refresh both live banks after building/publishing the reference.
        let current = self.reference.load(index: 0)
        let full = self.cache.load(index: 1)
        let initial = self.cache.load(index: 2)
        let history = HistoryOffsets::for_view(s, full, initial)
        let mut preview = self.preview_cache.load(index: 0)
        preview.history = history
        self.preview_cache.store(index: 0, value: preview)
        let mut bank: u32 = 0
        while bank < 2 {
            let active = current.active_valid == 1 && bank == current.active
            let pending = current.pending == 1 && bank == 1 - current.active
            if active || pending {
                let offset = self.anchor.load(index: bank).delta_from(s)
                let index = bank * 8195 + ORBIT_META_INDEX
                let metadata = self.orbit.load(index: index)
                self.orbit.store(index: index, value: metadata.with_center_offset(offset))
            }
            bank = bank + 1
        }
    }

    fn advance_preview(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).preview_dirty == 0 {
            return
        }
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 1 || preview.step_target == 0 {
            return
        }
        let s: MandelbrotViewState = self.state
        let x: u32 = invocation.global.x
        let y: u32 = invocation.global.y
        let px: i32 = to_i32(from_i32(__bitcast<u32, i32>(x)) * s.camera.res / 256.0)
        let py: i32 = to_i32(from_i32(__bitcast<u32, i32>(y)) * s.camera.res / 256.0)
        if !s.is_input_settled() {
            let tap: ReprojectionTap = reproject_coarse_pixel(
                s,
                self.cache.load(index: 1),
                self.cache.load(index: 2),
                preview.history,
                px,
                py,
            )
            if tap.reusable {
                return
            }
        }
        let index: u32 = (y << 8) | x
        let old: OrbitProgress = self.preview_progress.load(index: index)
        let saved: OrbitProgress = if old.epoch == preview.epoch {
            old
        } else {
            empty_progress(preview.epoch)
        }
        let done_for_chunk: bool = if saved.is_terminal(preview.budget) {
            true
        } else {
            saved.iteration >= preview.step_target
        }
        if done_for_chunk {
            if old.epoch != preview.epoch {
                self.preview_progress.store(index: index, value: saved)
            }
        } else {
            let next: OrbitProgress = continue_preview_pixel(
                self.orbit,
                preview.reference_bank * 8195,
                s.camera,
                PixelSample::ordered_2x2(px, py),
                preview.step_target,
                preview.step_target,
                preview.prefix_only == 1,
                saved,
            )
            self.preview_progress.store(index: index, value: next)
        }
    }

    fn render_preview(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).preview_dirty == 0 {
            return
        }
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.step_target == 0 {
            return
        }
        let s: MandelbrotViewState = self.state
        let x: u32 = invocation.global.x
        let y: u32 = invocation.global.y
        let index: u32 = (y << 8) | x
        let px: i32 = to_i32(from_i32(__bitcast<u32, i32>(x)) * s.camera.res / 256.0)
        let py: i32 = to_i32(from_i32(__bitcast<u32, i32>(y)) * s.camera.res / 256.0)
        let tap: ReprojectionTap = reproject_coarse_pixel(
            s,
            self.cache.load(index: 1),
            self.cache.load(index: 2),
            preview.history,
            px,
            py,
        )
        let cached: Color = if tap.use_full {
            sample_snapshot(self.snapshot_pixels, tap.sx, tap.sy, tap.old_res)
        } else {
            let scale: f32 = 256.0 / max(tap.old_res, 1.0)
            sample(self.initial_pixels, tap.sx * scale, tap.sy * scale)
        }
        let live_reusable: bool = if tap.reusable { !s.is_input_settled() } else { false }
        if live_reusable {
            self.pixels.store(index: index, value: cached)
        } else {
            let computed: OrbitProgress = self.preview_progress.load(index: index)
            let known_escaped: bool = computed.epoch == preview.epoch
                && computed.is_escaped()
                && !computed.is_glitched()
            let proven_interior: bool = computed.epoch == preview.epoch
                && !computed.is_escaped()
                && !computed.is_glitched()
                && preview.prefix_only == 0
                && computed.iteration >= preview.budget
            if known_escaped || proven_interior {
                let current: Color = unpack_lab(progress_color(computed))
                let result: Color = if tap.reusable {
                    blend(cached, current, progress(s.input_age(), 60.0, 300.0))
                } else {
                    current
                }
                self.pixels.store(index: index, value: result)
            } else if tap.reusable {
                self.pixels.store(index: index, value: cached)
            } else if preview.prefix_only == 0 && computed.is_glitched() {
                self.pixels.store(index: index, value: unpack_lab(interior()))
            } else {
                self.pixels.store(index: index, value: Color::default())
            }
        }
    }

    fn finish_preview(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        if self.cache.load(index: 0).preview_dirty == 0 {
            return
        }
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 1 || preview.step_target == 0 {
            return
        }
        let s: MandelbrotViewState = self.state
        let full: ViewCache = self.cache.load(index: 1)
        let initial: ViewCache = self.cache.load(index: 2)
        if !s.is_input_settled() && (full.completed == 1 || initial.completed == 1) {
            return
        }
        self.preview_cache.store(index: 0, value: preview.commit_step())
    }

    // Preserve the first settled preview before native refinement finishes.
    // Neither this image nor its camera metadata changes while input is live.
    fn cache_initial(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let c: ViewCache = self.cache.load(index: 0)
        let old: ViewCache = self.cache.load(index: 2)
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 0 || !ref_state.can_publish_initial(s, c.epoch, old.epoch) {
            return
        }
        let index: u32 = (invocation.global.y << 8) | invocation.global.x
        self.initial_pixels.store(
            index: index,
            value: self.pixels.load(index: index),
        )
    }

    fn publish_initial(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let c: ViewCache = self.cache.load(index: 0)
        let old: ViewCache = self.cache.load(index: 2)
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 0 || !ref_state.can_publish_initial(s, c.epoch, old.epoch) {
            return
        }
        self.cache.store(index: 2, value: c.as_published_initial())
    }

    fn blur_horizontal(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).blur_dirty == 0 {
            return
        }
        let sigma: f32 = self.reference.load(index: 0).blur_sigma(self.state)
        self.horizontal.store(
            index: (invocation.global.y << 8) | invocation.global.x,
            value: gaussian(
                self.pixels,
                invocation.global.x,
                invocation.global.y,
                sigma,
                false,
            ),
        )
    }

    fn blur_vertical(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).blur_dirty == 0 {
            return
        }
        let sigma: f32 = self.reference.load(index: 0).blur_sigma(self.state)
        self.blurred.store(
            index: (invocation.global.y << 8) | invocation.global.x,
            value: gaussian(
                self.horizontal,
                invocation.global.x,
                invocation.global.y,
                sigma,
                true,
            ),
        )
    }

    // Spatially interleaved phases cover the whole image, rather
    // than sweeping rectangles. Each orbit resumes its own saved recurrence.
    fn restore_oracle(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<16, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        if !s.is_input_settled() {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let history: ViewCache = self.cache.load(index: 1)
        let schedule: RefinementSchedule = RefinementSchedule::for_view(s.camera.zoom, s.camera.res)
        if history.completed == 0 || history.budget < schedule.limit {
            return
        }
        if !same_camera(history, c) {
            return
        }
        let pixel: CohortPixel = schedule.rect_pixel(
            c.cursor,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let saved: OrbitProgress = self.progress_pixels.load(index: index)
        if saved.is_presentable_in(c.epoch) {
            return
        }
        let deep: SampleOracle = self.snapshot_oracle.load(index: index)
        if !deep.is_usable() {
            return
        }
        let preserved: OrbitProgress = OrbitProgress::from_oracle(deep, c.epoch, s.clock)
        let base: u32 = progress_color(preserved)
        self.progress_pixels.store(index: index, value: preserved)
        self.native_pixels.store(index: index, value: base)
        let antialiased: u32 = if history.aa == s.antialias {
            self.snapshot_pixels.load(index: index)
        } else {
            base
        }
        self.antialiased_pixels.store(index: index, value: antialiased)
    }

    // A sparse, full-depth lattice reveals real results while the denser
    // checkpoints are still iterating. It shares their persistent buffers.
    fn seed_refinement(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<16, 16, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        if c.cursor >= 16 || c.completed == 1 {
            return
        }
        let lane: u32 = (invocation.global.y % 4) * 4 + invocation.global.x % 4
        let rank: u32 = c.cursor * 16 + lane
        let block: PackedReference = self.orbit.load(index: 16390 + (rank >> 5))
        let pixel: CohortPixel = seed_pixel(
            block,
            rank,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let old: OrbitProgress = self.progress_pixels.load(index: index)
        if old.is_presentable_in(c.epoch) {
            return
        }
        let saved: OrbitProgress = if old.epoch == c.epoch {
            old
        } else {
            empty_progress(c.epoch)
        }
        let limit: u32 = iteration_limit(s.camera.zoom)
        let next: OrbitProgress = continue_pixel(
            self.orbit,
            ref_state.active * 8195,
            s.camera,
            pixel.sample(),
            limit,
            limit,
            saved,
        )
        self.progress_pixels.store(
            index: index,
            value: next.with_fade_start(s.clock),
        )
        let bits: u32 = progress_color(next)
        self.native_pixels.store(index: index, value: bits)
        self.antialiased_pixels.store(index: index, value: bits)
    }

    fn refine_pixels(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<16, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let schedule: RefinementSchedule = RefinementSchedule::for_view(s.camera.zoom, s.camera.res)
        let pixel: CohortPixel = schedule.rect_pixel(
            c.cursor,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let old: OrbitProgress = self.progress_pixels.load(index: index)
        let saved: OrbitProgress = if old.epoch == c.epoch {
            old
        } else {
            empty_progress(c.epoch)
        }
        if saved.is_terminal(schedule.limit) {
            return
        }
        let next: OrbitProgress = continue_pixel(
            self.orbit,
            ref_state.active * 8195,
            s.camera,
            pixel.sample(),
            schedule.limit,
            2048,
            saved,
        )
        // Once terminal, z_re is free to hold the pixel's fade start time.
        let stored: OrbitProgress = if next.is_terminal(schedule.limit) {
            next.with_fade_start(s.clock)
        } else {
            next
        }
        self.progress_pixels.store(index: index, value: stored)
        let bits: u32 = progress_color(next)
        self.native_pixels.store(index: index, value: bits)
        self.antialiased_pixels.store(index: index, value: bits)
    }

    fn antialias_pixels(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let schedule: RefinementSchedule = RefinementSchedule::for_view(s.camera.zoom, s.camera.res)
        let pixel: CohortPixel = schedule.aa_pixel(
            c.cursor,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let bits: u32 = self.native_pixels.load(index: index)
        let center: Color = unpack_lab(bits)
        let (left_i, right_i, up_i, down_i) = pixel.pixel.clamped_neighbor_indices(s.camera.res)
        let edge: f32 = max(
            max(
                contrast(center, unpack_lab(self.native_pixels.load(index: left_i))),
                contrast(center, unpack_lab(self.native_pixels.load(index: right_i))),
            ),
            max(
                contrast(center, unpack_lab(self.native_pixels.load(index: up_i))),
                contrast(center, unpack_lab(self.native_pixels.load(index: down_i))),
            ),
        )
        if s.antialias >= 0.5 && edge > 0.12 {
            let camera: Camera = s.camera
            let base: u32 = ref_state.active * 8195
            let a: Color = unpack_lab(sample_pixel(
                self.orbit,
                base,
                camera,
                pixel.offset_sample(Vec2 { x: 0.28, y: -0.28 }),
                schedule.limit,
            ))
            let b: Color = unpack_lab(sample_pixel(
                self.orbit,
                base,
                camera,
                pixel.offset_sample(Vec2 { x: -0.28, y: 0.28 }),
                schedule.limit,
            ))
            let averaged: Color = ((center + a) + b) / 3.0
            self.antialiased_pixels.store(
                index: index,
                value: pack_lab(averaged),
            )
        }
    }

    fn finish_refinement(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let end: u32 = RefinementSchedule::for_view(s.camera.zoom, s.camera.res).total_steps()
        if c.cursor >= end {
            return
        }
        self.cache.store(index: 0, value: c.advance_cursor(end))
    }

    fn cache_snapshot(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let c: ViewCache = self.cache.load(index: 0)
        let snapshot: ViewCache = self.cache.load(index: 1)
        if c.completed == 0 || snapshot.epoch == c.epoch {
            return
        }
        // Copy only on publication. Small dispatch also makes the idle guard
        // cheap; coalesced lanes cover the fixed-stride image in 64 strips.
        let lane: u32 = (invocation.global.y << 8) | invocation.global.x
        let mut strip: u32 = 0
        while strip < 64 {
            let index: u32 = lane + (strip << 16)
            let pixel: Pixel = Pixel {
                x: index & 2047,
                y: index >> 11,
            }
            if pixel.in_extent(s.camera.res) {
                self.snapshot_pixels.store(
                    index: index,
                    value: self.antialiased_pixels.load(index: index),
                )
                let result: OrbitProgress = self.progress_pixels.load(index: index)
                self.snapshot_oracle.store(index: index, value: result.to_oracle())
            }
            strip = strip + 1
        }
    }

    fn publish_snapshot(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let c: ViewCache = self.cache.load(index: 0)
        if c.completed == 1 {
            self.cache.store(index: 1, value: c)
        }
    }

    fn display_preview(self, px: i32, py: i32) -> i32 uses (FragmentSurface) {
        let s: MandelbrotViewState = self.state
        let pixel: Pixel = Pixel {
            x: __bitcast<i32, u32>(px) & 2047,
            y: __bitcast<i32, u32>(py) & 2047,
        }
        let index: u32 = pixel.native_index()
        let c: ViewCache = self.cache.load(index: 0)
        let reference_state: ReferenceControl = self.reference.load(index: 0)
        let reveal: f32 = sharpness(reference_state.display_age(s))
        let saved: OrbitProgress = self.progress_pixels.load(index: index)
        if saved.is_presentable_in(c.epoch) {
            let bits: u32 = self.antialiased_pixels.load(index: index)
            let amount: f32 = progress(s.clock - saved.fade_started_at(), 0.0, 350.0) * reveal
            if amount >= 1.0 {
                return display_rgba(unpack_lab(bits))
            }
            let coarse: Color = sample(
                self.blurred,
                from_i32(px) * 256.0 / s.camera.res,
                from_i32(py) * 256.0 / s.camera.res,
            )
            return display_rgba(blend(coarse, unpack_lab(bits), amount))
        }
        let coarse: Color = sample(
            self.blurred,
            from_i32(px) * 256.0 / s.camera.res,
            from_i32(py) * 256.0 / s.camera.res,
        )
        let stride: f32 = from_i32(to_i32((s.camera.res + 511.0) / 512.0))
        let tap: BilinearTap = lattice_tap(px, py, stride, s.camera.res - 1.0)
        let a: OrbitProgress = self.progress_pixels.load(index: tap.i00)
        let b: OrbitProgress = self.progress_pixels.load(index: tap.i10)
        let d: OrbitProgress = self.progress_pixels.load(index: tap.i01)
        let e: OrbitProgress = self.progress_pixels.load(index: tap.i11)
        let ready: bool = a.is_presentable_in(c.epoch)
            && b.is_presentable_in(c.epoch)
            && d.is_presentable_in(c.epoch)
            && e.is_presentable_in(c.epoch)
        if ready {
            let sparse: Color = blend_corners(
                unpack_lab(self.native_pixels.load(index: tap.i00)),
                unpack_lab(self.native_pixels.load(index: tap.i10)),
                unpack_lab(self.native_pixels.load(index: tap.i01)),
                unpack_lab(self.native_pixels.load(index: tap.i11)),
                tap.tx,
                tap.ty,
            )
            let latest_fade: f32 = finite_max(
                finite_max(a.fade_started_at(), b.fade_started_at()),
                finite_max(d.fade_started_at(), e.fade_started_at()),
            )
            let since: f32 = s.clock - latest_fade
            display_rgba(blend(coarse, sparse, progress(since, 0.0, 350.0) * reveal))
        } else {
            display_rgba(coarse)
        }
    }

    fn sync_url(self, event: own SurfaceLocationEvent) -> SurfaceStateEnvelope
        uses (SurfaceLocationTransition)
    {
        SurfaceStateEnvelope { state: sync_url_state(self.state, event) }
    }

    fn contact(self, event: own SurfaceContactEvent) -> SurfaceStateEnvelope
        uses (SurfaceContactTransition)
    {
        SurfaceStateEnvelope { state: contact_transition(self.state, event) }
    }

    fn navigate(self, event: own SurfaceEvent) -> SurfaceStateEnvelope
        uses (SurfaceTransition, SurfaceScheduling<ContinuousFrames>)
    {
        SurfaceStateEnvelope {
            state: transition(self.state, event),
        }
    }
}

snapshot_pixels: actor SmoothPerturbationalMandelbrot uses (
    GpuProgram<WebGpuBackend>,
    SurfaceQuality<SharpBacking>,
    SurfaceRecovery<StandardSurfaceRecovery>,
) {
    orbit: StorageBuffer<PackedReference, ORBIT_CAPACITY>,
    pixels: StorageBuffer<Color, 65536>,
    initial_pixels: StorageBuffer<Color, 65536>,
    preview_progress: StorageBuffer<OrbitProgress, 65536>,
    preview_cache: StorageBuffer<PreviewCache, 1>,
    snapshot_oracle: StorageBuffer<SampleOracle, 4194304>,
    horizontal: StorageBuffer<Color, 65536>,
    blurred: StorageBuffer<Color, 65536>,
    cache: StorageBuffer<ViewCache, 3>,
    anchor: StorageBuffer<ReferenceAnchor, 2>,
    reference: StorageBuffer<ReferenceControl, 1>,
    reference_words: StorageBuffer<u32, 16>,
    native_pixels: StorageBuffer<u32, 4194304>,
    antialiased_pixels: StorageBuffer<u32, 4194304>,
    progress_pixels: StorageBuffer<OrbitProgress, 4194304>,
    snapshot_pixels: StorageBuffer<u32, 4194304>,
    state: MandelbrotViewState,

    fn initial() -> SurfaceStateEnvelope uses (core::actor::InitialState) {
        initial_state()
    }

    const fn view() -> Surface<MandelbrotParams> {
        Surface {
            extent: Extent::square(2048),
            params: mandelbrot_params(),
        }
    }

    fn initialize_order(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let r: ReferenceControl = self.reference.load(index: 0)
        if r.active_valid == 1 || r.pending == 1 {
            return
        }
        self.orbit.store(
            index: 16390 + invocation.global.x,
            value: order_block(invocation.global.x),
        )
    }

    // Validate a candidate against the latest view before doing more work.
    fn discard_stale_reference(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let control: ReferenceControl = self.reference.load(index: 0)
        if control.pending == 0 {
            return
        }
        let bank: u32 = if control.active == 0 { 1 } else { 0 }
        let candidate: ReferenceAnchor = self.anchor.load(index: bank)
        let delta: Complex<f32> = candidate.delta_from(s)
        if candidate.limit < iteration_limit(s.camera.zoom)
            || max(abs(delta.re), abs(delta.im)) > s.camera.zoom * 0.5
        {
            self.reference.store(index: 0, value: control.cancel_pending())
        }
    }

    fn build_reference(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let previous: ViewCache = self.cache.load(index: 0)
        let initial: ViewCache = self.cache.load(index: 2)
        let previous_preview: PreviewCache = self.preview_cache.load(index: 0)
        let age: f32 = s.input_age()
        let budget: u32 = preview_budget(s.camera.zoom)
        let control: ReferenceControl = self.reference.load(index: 0)
        let active_anchor: ReferenceAnchor = self.anchor.load(index: control.active)
        let delta: Complex<f32> = active_anchor.delta_from(s)
        let target: u32 = iteration_limit(s.camera.zoom)
        let reusable: bool = control.active_valid == 1
            && active_anchor.limit >= target
            && abs(delta.re) <= s.camera.zoom * 0.125
            && abs(delta.im) <= s.camera.zoom * 0.125
        // Keep the active orbit available while a replacement advances in
        // bounded exact-integer batches. Pointer input never queues behind
        // an entire multi-thousand-step reference recurrence.
        let keep_active: bool = if control.pending == 0 { reusable } else { false }
        let defer_rebuild: bool = if control.active_valid == 1 { age < 60.0 } else { false }
        let skip_build: bool = if keep_active { true } else { defer_rebuild }
        if skip_build {
            let preview_bank: u32 = control.preview_bank(s)
            let preview_anchor: ReferenceAnchor = self.anchor.load(index: preview_bank)
            let next_preview: PreviewCache = previous_preview.sync_with_view(
                s,
                control,
                preview_anchor.generation,
                budget,
            )
            self.preview_cache.store(index: 0, value: next_preview)
            self.cache.store(
                index: 0,
                value: previous.sync_for_frame(s, control, next_preview, initial),
            )
        } else {
            let bank: u32 = 1 - control.active
            let base: u32 = bank * 8195
            let existing_pending: ReferenceAnchor = self.anchor.load(index: bank)
            let next_gen: u32 = (if active_anchor.generation > existing_pending.generation {
                active_anchor.generation
            } else {
                existing_pending.generation
            }) + 1
            let pending_anchor: ReferenceAnchor = if control.pending == 0 {
                let created: ReferenceAnchor = ReferenceAnchor::from_state(s, target, next_gen)
                self.anchor.store(index: bank, value: created)
                clear_reference_checkpoint(self.reference_words)
                self.orbit.store(index: base, value: PackedReference::zero())
                created
            } else {
                existing_pending
            }
            let center: Complex<ReferenceReal> = reference_center(pending_anchor)
            let mut z: Complex<ReferenceReal> = if control.pending == 0 {
                Complex::default()
            } else {
                load_reference_checkpoint(self.reference_words, control)
            }
            let mut i: u32 = if control.pending == 0 { 0 } else { control.index }
            let mut step: u32 = 0
            let mut escaped: bool = false
            while step < 64 && i < pending_anchor.limit && !escaped {
                let result: ReferenceStep = reference_step(z, center)
                escaped = result.escaped
                if !escaped {
                    z = result.value
                    self.orbit.store(
                        index: base + i + 1,
                        value: PackedReference::from_fixed(z),
                    )
                    i = i + 1
                }
                step = step + 1
            }
            self.orbit.store(
                index: base + ORBIT_CENTER_INDEX,
                value: PackedReference::from_fixed(center),
            )
            self.orbit.store(
                index: base + ORBIT_META_INDEX,
                value: PackedReference::from_metadata(i + 1, pending_anchor.limit),
            )
            let published: bool = escaped || i >= pending_anchor.limit
            let next_control: ReferenceControl = if published {
                ReferenceControl::publish(bank, i, z.re.sign, z.im.sign, s.clock)
            } else {
                store_reference_checkpoint(self.reference_words, z)
                control.advance_pending(i, z.re.sign, z.im.sign)
            }
            self.reference.store(index: 0, value: next_control)
            // Checkpoints belong to the orbit actually selected for preview.
            // During live input that can still be the active bank while its
            // replacement is being built in the other bank.
            let preview_bank: u32 = next_control.preview_bank(s)
            let preview_anchor: ReferenceAnchor = self.anchor.load(index: preview_bank)
            let next_preview: PreviewCache = previous_preview.sync_with_view(
                s,
                next_control,
                preview_anchor.generation,
                budget,
            )
            self.preview_cache.store(index: 0, value: next_preview)
            let synced_view: ViewCache = previous.sync_for_frame(
                s,
                next_control,
                next_preview,
                initial,
            )
            let next_view: ViewCache = if published {
                synced_view.invalidate_for_new_reference()
            } else {
                synced_view
            }
            self.cache.store(index: 0, value: next_view)
        }
        // Integer center differences are camera work, not per-pixel work.
        // Refresh both live banks after building/publishing the reference.
        let current = self.reference.load(index: 0)
        let full = self.cache.load(index: 1)
        let initial = self.cache.load(index: 2)
        let history = HistoryOffsets::for_view(s, full, initial)
        let mut preview = self.preview_cache.load(index: 0)
        preview.history = history
        self.preview_cache.store(index: 0, value: preview)
        let mut bank: u32 = 0
        while bank < 2 {
            let active = current.active_valid == 1 && bank == current.active
            let pending = current.pending == 1 && bank == 1 - current.active
            if active || pending {
                let offset = self.anchor.load(index: bank).delta_from(s)
                let index = bank * 8195 + ORBIT_META_INDEX
                let metadata = self.orbit.load(index: index)
                self.orbit.store(index: index, value: metadata.with_center_offset(offset))
            }
            bank = bank + 1
        }
    }

    fn advance_preview(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).preview_dirty == 0 {
            return
        }
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 1 || preview.step_target == 0 {
            return
        }
        let s: MandelbrotViewState = self.state
        let x: u32 = invocation.global.x
        let y: u32 = invocation.global.y
        let px: i32 = to_i32(from_i32(__bitcast<u32, i32>(x)) * s.camera.res / 256.0)
        let py: i32 = to_i32(from_i32(__bitcast<u32, i32>(y)) * s.camera.res / 256.0)
        if !s.is_input_settled() {
            let tap: ReprojectionTap = reproject_coarse_pixel(
                s,
                self.cache.load(index: 1),
                self.cache.load(index: 2),
                preview.history,
                px,
                py,
            )
            if tap.reusable {
                return
            }
        }
        let index: u32 = (y << 8) | x
        let old: OrbitProgress = self.preview_progress.load(index: index)
        let saved: OrbitProgress = if old.epoch == preview.epoch {
            old
        } else {
            empty_progress(preview.epoch)
        }
        let done_for_chunk: bool = if saved.is_terminal(preview.budget) {
            true
        } else {
            saved.iteration >= preview.step_target
        }
        if done_for_chunk {
            if old.epoch != preview.epoch {
                self.preview_progress.store(index: index, value: saved)
            }
        } else {
            let next: OrbitProgress = continue_preview_pixel(
                self.orbit,
                preview.reference_bank * 8195,
                s.camera,
                PixelSample::ordered_2x2(px, py),
                preview.step_target,
                preview.step_target,
                preview.prefix_only == 1,
                saved,
            )
            self.preview_progress.store(index: index, value: next)
        }
    }

    fn render_preview(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).preview_dirty == 0 {
            return
        }
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.step_target == 0 {
            return
        }
        let s: MandelbrotViewState = self.state
        let x: u32 = invocation.global.x
        let y: u32 = invocation.global.y
        let index: u32 = (y << 8) | x
        let px: i32 = to_i32(from_i32(__bitcast<u32, i32>(x)) * s.camera.res / 256.0)
        let py: i32 = to_i32(from_i32(__bitcast<u32, i32>(y)) * s.camera.res / 256.0)
        let tap: ReprojectionTap = reproject_coarse_pixel(
            s,
            self.cache.load(index: 1),
            self.cache.load(index: 2),
            preview.history,
            px,
            py,
        )
        let cached: Color = if tap.use_full {
            sample_snapshot(self.snapshot_pixels, tap.sx, tap.sy, tap.old_res)
        } else {
            let scale: f32 = 256.0 / max(tap.old_res, 1.0)
            sample(self.initial_pixels, tap.sx * scale, tap.sy * scale)
        }
        let live_reusable: bool = if tap.reusable { !s.is_input_settled() } else { false }
        if live_reusable {
            self.pixels.store(index: index, value: cached)
        } else {
            let computed: OrbitProgress = self.preview_progress.load(index: index)
            let known_escaped: bool = computed.epoch == preview.epoch
                && computed.is_escaped()
                && !computed.is_glitched()
            let proven_interior: bool = computed.epoch == preview.epoch
                && !computed.is_escaped()
                && !computed.is_glitched()
                && preview.prefix_only == 0
                && computed.iteration >= preview.budget
            if known_escaped || proven_interior {
                let current: Color = unpack_lab(progress_color(computed))
                let result: Color = if tap.reusable {
                    blend(cached, current, progress(s.input_age(), 60.0, 300.0))
                } else {
                    current
                }
                self.pixels.store(index: index, value: result)
            } else if tap.reusable {
                self.pixels.store(index: index, value: cached)
            } else if preview.prefix_only == 0 && computed.is_glitched() {
                self.pixels.store(index: index, value: unpack_lab(interior()))
            } else {
                self.pixels.store(index: index, value: Color::default())
            }
        }
    }

    fn finish_preview(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        if self.cache.load(index: 0).preview_dirty == 0 {
            return
        }
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 1 || preview.step_target == 0 {
            return
        }
        let s: MandelbrotViewState = self.state
        let full: ViewCache = self.cache.load(index: 1)
        let initial: ViewCache = self.cache.load(index: 2)
        if !s.is_input_settled() && (full.completed == 1 || initial.completed == 1) {
            return
        }
        self.preview_cache.store(index: 0, value: preview.commit_step())
    }

    // Preserve the first settled preview before native refinement finishes.
    // Neither this image nor its camera metadata changes while input is live.
    fn cache_initial(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let c: ViewCache = self.cache.load(index: 0)
        let old: ViewCache = self.cache.load(index: 2)
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 0 || !ref_state.can_publish_initial(s, c.epoch, old.epoch) {
            return
        }
        let index: u32 = (invocation.global.y << 8) | invocation.global.x
        self.initial_pixels.store(
            index: index,
            value: self.pixels.load(index: index),
        )
    }

    fn publish_initial(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let c: ViewCache = self.cache.load(index: 0)
        let old: ViewCache = self.cache.load(index: 2)
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 0 || !ref_state.can_publish_initial(s, c.epoch, old.epoch) {
            return
        }
        self.cache.store(index: 2, value: c.as_published_initial())
    }

    fn blur_horizontal(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).blur_dirty == 0 {
            return
        }
        let sigma: f32 = self.reference.load(index: 0).blur_sigma(self.state)
        self.horizontal.store(
            index: (invocation.global.y << 8) | invocation.global.x,
            value: gaussian(
                self.pixels,
                invocation.global.x,
                invocation.global.y,
                sigma,
                false,
            ),
        )
    }

    fn blur_vertical(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).blur_dirty == 0 {
            return
        }
        let sigma: f32 = self.reference.load(index: 0).blur_sigma(self.state)
        self.blurred.store(
            index: (invocation.global.y << 8) | invocation.global.x,
            value: gaussian(
                self.horizontal,
                invocation.global.x,
                invocation.global.y,
                sigma,
                true,
            ),
        )
    }

    // Spatially interleaved phases cover the whole image, rather
    // than sweeping rectangles. Each orbit resumes its own saved recurrence.
    fn restore_oracle(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<16, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        if !s.is_input_settled() {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let history: ViewCache = self.cache.load(index: 1)
        let schedule: RefinementSchedule = RefinementSchedule::for_view(s.camera.zoom, s.camera.res)
        if history.completed == 0 || history.budget < schedule.limit {
            return
        }
        if !same_camera(history, c) {
            return
        }
        let pixel: CohortPixel = schedule.rect_pixel(
            c.cursor,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let saved: OrbitProgress = self.progress_pixels.load(index: index)
        if saved.is_presentable_in(c.epoch) {
            return
        }
        let deep: SampleOracle = self.snapshot_oracle.load(index: index)
        if !deep.is_usable() {
            return
        }
        let preserved: OrbitProgress = OrbitProgress::from_oracle(deep, c.epoch, s.clock)
        let base: u32 = progress_color(preserved)
        self.progress_pixels.store(index: index, value: preserved)
        self.native_pixels.store(index: index, value: base)
        let antialiased: u32 = if history.aa == s.antialias {
            self.snapshot_pixels.load(index: index)
        } else {
            base
        }
        self.antialiased_pixels.store(index: index, value: antialiased)
    }

    // A sparse, full-depth lattice reveals real results while the denser
    // checkpoints are still iterating. It shares their persistent buffers.
    fn seed_refinement(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<16, 16, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        if c.cursor >= 16 || c.completed == 1 {
            return
        }
        let lane: u32 = (invocation.global.y % 4) * 4 + invocation.global.x % 4
        let rank: u32 = c.cursor * 16 + lane
        let block: PackedReference = self.orbit.load(index: 16390 + (rank >> 5))
        let pixel: CohortPixel = seed_pixel(
            block,
            rank,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let old: OrbitProgress = self.progress_pixels.load(index: index)
        if old.is_presentable_in(c.epoch) {
            return
        }
        let saved: OrbitProgress = if old.epoch == c.epoch {
            old
        } else {
            empty_progress(c.epoch)
        }
        let limit: u32 = iteration_limit(s.camera.zoom)
        let next: OrbitProgress = continue_pixel(
            self.orbit,
            ref_state.active * 8195,
            s.camera,
            pixel.sample(),
            limit,
            limit,
            saved,
        )
        self.progress_pixels.store(
            index: index,
            value: next.with_fade_start(s.clock),
        )
        let bits: u32 = progress_color(next)
        self.native_pixels.store(index: index, value: bits)
        self.antialiased_pixels.store(index: index, value: bits)
    }

    fn refine_pixels(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<16, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let schedule: RefinementSchedule = RefinementSchedule::for_view(s.camera.zoom, s.camera.res)
        let pixel: CohortPixel = schedule.rect_pixel(
            c.cursor,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let old: OrbitProgress = self.progress_pixels.load(index: index)
        let saved: OrbitProgress = if old.epoch == c.epoch {
            old
        } else {
            empty_progress(c.epoch)
        }
        if saved.is_terminal(schedule.limit) {
            return
        }
        let next: OrbitProgress = continue_pixel(
            self.orbit,
            ref_state.active * 8195,
            s.camera,
            pixel.sample(),
            schedule.limit,
            2048,
            saved,
        )
        // Once terminal, z_re is free to hold the pixel's fade start time.
        let stored: OrbitProgress = if next.is_terminal(schedule.limit) {
            next.with_fade_start(s.clock)
        } else {
            next
        }
        self.progress_pixels.store(index: index, value: stored)
        let bits: u32 = progress_color(next)
        self.native_pixels.store(index: index, value: bits)
        self.antialiased_pixels.store(index: index, value: bits)
    }

    fn antialias_pixels(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let schedule: RefinementSchedule = RefinementSchedule::for_view(s.camera.zoom, s.camera.res)
        let pixel: CohortPixel = schedule.aa_pixel(
            c.cursor,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let bits: u32 = self.native_pixels.load(index: index)
        let center: Color = unpack_lab(bits)
        let (left_i, right_i, up_i, down_i) = pixel.pixel.clamped_neighbor_indices(s.camera.res)
        let edge: f32 = max(
            max(
                contrast(center, unpack_lab(self.native_pixels.load(index: left_i))),
                contrast(center, unpack_lab(self.native_pixels.load(index: right_i))),
            ),
            max(
                contrast(center, unpack_lab(self.native_pixels.load(index: up_i))),
                contrast(center, unpack_lab(self.native_pixels.load(index: down_i))),
            ),
        )
        if s.antialias >= 0.5 && edge > 0.12 {
            let camera: Camera = s.camera
            let base: u32 = ref_state.active * 8195
            let a: Color = unpack_lab(sample_pixel(
                self.orbit,
                base,
                camera,
                pixel.offset_sample(Vec2 { x: 0.28, y: -0.28 }),
                schedule.limit,
            ))
            let b: Color = unpack_lab(sample_pixel(
                self.orbit,
                base,
                camera,
                pixel.offset_sample(Vec2 { x: -0.28, y: 0.28 }),
                schedule.limit,
            ))
            let averaged: Color = ((center + a) + b) / 3.0
            self.antialiased_pixels.store(
                index: index,
                value: pack_lab(averaged),
            )
        }
    }

    fn finish_refinement(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let end: u32 = RefinementSchedule::for_view(s.camera.zoom, s.camera.res).total_steps()
        if c.cursor >= end {
            return
        }
        self.cache.store(index: 0, value: c.advance_cursor(end))
    }

    fn cache_snapshot(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let c: ViewCache = self.cache.load(index: 0)
        let snapshot: ViewCache = self.cache.load(index: 1)
        if c.completed == 0 || snapshot.epoch == c.epoch {
            return
        }
        // Copy only on publication. Small dispatch also makes the idle guard
        // cheap; coalesced lanes cover the fixed-stride image in 64 strips.
        let lane: u32 = (invocation.global.y << 8) | invocation.global.x
        let mut strip: u32 = 0
        while strip < 64 {
            let index: u32 = lane + (strip << 16)
            let pixel: Pixel = Pixel {
                x: index & 2047,
                y: index >> 11,
            }
            if pixel.in_extent(s.camera.res) {
                self.snapshot_pixels.store(
                    index: index,
                    value: self.antialiased_pixels.load(index: index),
                )
                let result: OrbitProgress = self.progress_pixels.load(index: index)
                self.snapshot_oracle.store(index: index, value: result.to_oracle())
            }
            strip = strip + 1
        }
    }

    fn publish_snapshot(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let c: ViewCache = self.cache.load(index: 0)
        if c.completed == 1 {
            self.cache.store(index: 1, value: c)
        }
    }

    fn display_preview(self, px: i32, py: i32) -> i32 uses (FragmentSurface) {
        let s: MandelbrotViewState = self.state
        let pixel: Pixel = Pixel {
            x: __bitcast<i32, u32>(px) & 2047,
            y: __bitcast<i32, u32>(py) & 2047,
        }
        let index: u32 = pixel.native_index()
        let c: ViewCache = self.cache.load(index: 0)
        let reference_state: ReferenceControl = self.reference.load(index: 0)
        let reveal: f32 = sharpness(reference_state.display_age(s))
        let saved: OrbitProgress = self.progress_pixels.load(index: index)
        if saved.is_presentable_in(c.epoch) {
            let bits: u32 = self.antialiased_pixels.load(index: index)
            let amount: f32 = progress(s.clock - saved.fade_started_at(), 0.0, 350.0) * reveal
            if amount >= 1.0 {
                return display_rgba(unpack_lab(bits))
            }
            let coarse: Color = sample(
                self.blurred,
                from_i32(px) * 256.0 / s.camera.res,
                from_i32(py) * 256.0 / s.camera.res,
            )
            return display_rgba(blend(coarse, unpack_lab(bits), amount))
        }
        let coarse: Color = sample(
            self.blurred,
            from_i32(px) * 256.0 / s.camera.res,
            from_i32(py) * 256.0 / s.camera.res,
        )
        let stride: f32 = from_i32(to_i32((s.camera.res + 511.0) / 512.0))
        let tap: BilinearTap = lattice_tap(px, py, stride, s.camera.res - 1.0)
        let a: OrbitProgress = self.progress_pixels.load(index: tap.i00)
        let b: OrbitProgress = self.progress_pixels.load(index: tap.i10)
        let d: OrbitProgress = self.progress_pixels.load(index: tap.i01)
        let e: OrbitProgress = self.progress_pixels.load(index: tap.i11)
        let ready: bool = a.is_presentable_in(c.epoch)
            && b.is_presentable_in(c.epoch)
            && d.is_presentable_in(c.epoch)
            && e.is_presentable_in(c.epoch)
        if ready {
            let sparse: Color = blend_corners(
                unpack_lab(self.native_pixels.load(index: tap.i00)),
                unpack_lab(self.native_pixels.load(index: tap.i10)),
                unpack_lab(self.native_pixels.load(index: tap.i01)),
                unpack_lab(self.native_pixels.load(index: tap.i11)),
                tap.tx,
                tap.ty,
            )
            let latest_fade: f32 = finite_max(
                finite_max(a.fade_started_at(), b.fade_started_at()),
                finite_max(d.fade_started_at(), e.fade_started_at()),
            )
            let since: f32 = s.clock - latest_fade
            display_rgba(blend(coarse, sparse, progress(since, 0.0, 350.0) * reveal))
        } else {
            display_rgba(coarse)
        }
    }

    fn sync_url(self, event: own SurfaceLocationEvent) -> SurfaceStateEnvelope
        uses (SurfaceLocationTransition)
    {
        SurfaceStateEnvelope { state: sync_url_state(self.state, event) }
    }

    fn contact(self, event: own SurfaceContactEvent) -> SurfaceStateEnvelope
        uses (SurfaceContactTransition)
    {
        SurfaceStateEnvelope { state: contact_transition(self.state, event) }
    }

    fn navigate(self, event: own SurfaceEvent) -> SurfaceStateEnvelope
        uses (SurfaceTransition, SurfaceScheduling<ContinuousFrames>)
    {
        SurfaceStateEnvelope {
            state: transition(self.state, event),
        }
    }
}

state: actor SmoothPerturbationalMandelbrot uses (
    GpuProgram<WebGpuBackend>,
    SurfaceQuality<SharpBacking>,
    SurfaceRecovery<StandardSurfaceRecovery>,
) {
    orbit: StorageBuffer<PackedReference, ORBIT_CAPACITY>,
    pixels: StorageBuffer<Color, 65536>,
    initial_pixels: StorageBuffer<Color, 65536>,
    preview_progress: StorageBuffer<OrbitProgress, 65536>,
    preview_cache: StorageBuffer<PreviewCache, 1>,
    snapshot_oracle: StorageBuffer<SampleOracle, 4194304>,
    horizontal: StorageBuffer<Color, 65536>,
    blurred: StorageBuffer<Color, 65536>,
    cache: StorageBuffer<ViewCache, 3>,
    anchor: StorageBuffer<ReferenceAnchor, 2>,
    reference: StorageBuffer<ReferenceControl, 1>,
    reference_words: StorageBuffer<u32, 16>,
    native_pixels: StorageBuffer<u32, 4194304>,
    antialiased_pixels: StorageBuffer<u32, 4194304>,
    progress_pixels: StorageBuffer<OrbitProgress, 4194304>,
    snapshot_pixels: StorageBuffer<u32, 4194304>,
    state: MandelbrotViewState,

    fn initial() -> SurfaceStateEnvelope uses (core::actor::InitialState) {
        initial_state()
    }

    const fn view() -> Surface<MandelbrotParams> {
        Surface {
            extent: Extent::square(2048),
            params: mandelbrot_params(),
        }
    }

    fn initialize_order(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let r: ReferenceControl = self.reference.load(index: 0)
        if r.active_valid == 1 || r.pending == 1 {
            return
        }
        self.orbit.store(
            index: 16390 + invocation.global.x,
            value: order_block(invocation.global.x),
        )
    }

    // Validate a candidate against the latest view before doing more work.
    fn discard_stale_reference(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let control: ReferenceControl = self.reference.load(index: 0)
        if control.pending == 0 {
            return
        }
        let bank: u32 = if control.active == 0 { 1 } else { 0 }
        let candidate: ReferenceAnchor = self.anchor.load(index: bank)
        let delta: Complex<f32> = candidate.delta_from(s)
        if candidate.limit < iteration_limit(s.camera.zoom)
            || max(abs(delta.re), abs(delta.im)) > s.camera.zoom * 0.5
        {
            self.reference.store(index: 0, value: control.cancel_pending())
        }
    }

    fn build_reference(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let previous: ViewCache = self.cache.load(index: 0)
        let initial: ViewCache = self.cache.load(index: 2)
        let previous_preview: PreviewCache = self.preview_cache.load(index: 0)
        let age: f32 = s.input_age()
        let budget: u32 = preview_budget(s.camera.zoom)
        let control: ReferenceControl = self.reference.load(index: 0)
        let active_anchor: ReferenceAnchor = self.anchor.load(index: control.active)
        let delta: Complex<f32> = active_anchor.delta_from(s)
        let target: u32 = iteration_limit(s.camera.zoom)
        let reusable: bool = control.active_valid == 1
            && active_anchor.limit >= target
            && abs(delta.re) <= s.camera.zoom * 0.125
            && abs(delta.im) <= s.camera.zoom * 0.125
        // Keep the active orbit available while a replacement advances in
        // bounded exact-integer batches. Pointer input never queues behind
        // an entire multi-thousand-step reference recurrence.
        let keep_active: bool = if control.pending == 0 { reusable } else { false }
        let defer_rebuild: bool = if control.active_valid == 1 { age < 60.0 } else { false }
        let skip_build: bool = if keep_active { true } else { defer_rebuild }
        if skip_build {
            let preview_bank: u32 = control.preview_bank(s)
            let preview_anchor: ReferenceAnchor = self.anchor.load(index: preview_bank)
            let next_preview: PreviewCache = previous_preview.sync_with_view(
                s,
                control,
                preview_anchor.generation,
                budget,
            )
            self.preview_cache.store(index: 0, value: next_preview)
            self.cache.store(
                index: 0,
                value: previous.sync_for_frame(s, control, next_preview, initial),
            )
        } else {
            let bank: u32 = 1 - control.active
            let base: u32 = bank * 8195
            let existing_pending: ReferenceAnchor = self.anchor.load(index: bank)
            let next_gen: u32 = (if active_anchor.generation > existing_pending.generation {
                active_anchor.generation
            } else {
                existing_pending.generation
            }) + 1
            let pending_anchor: ReferenceAnchor = if control.pending == 0 {
                let created: ReferenceAnchor = ReferenceAnchor::from_state(s, target, next_gen)
                self.anchor.store(index: bank, value: created)
                clear_reference_checkpoint(self.reference_words)
                self.orbit.store(index: base, value: PackedReference::zero())
                created
            } else {
                existing_pending
            }
            let center: Complex<ReferenceReal> = reference_center(pending_anchor)
            let mut z: Complex<ReferenceReal> = if control.pending == 0 {
                Complex::default()
            } else {
                load_reference_checkpoint(self.reference_words, control)
            }
            let mut i: u32 = if control.pending == 0 { 0 } else { control.index }
            let mut step: u32 = 0
            let mut escaped: bool = false
            while step < 64 && i < pending_anchor.limit && !escaped {
                let result: ReferenceStep = reference_step(z, center)
                escaped = result.escaped
                if !escaped {
                    z = result.value
                    self.orbit.store(
                        index: base + i + 1,
                        value: PackedReference::from_fixed(z),
                    )
                    i = i + 1
                }
                step = step + 1
            }
            self.orbit.store(
                index: base + ORBIT_CENTER_INDEX,
                value: PackedReference::from_fixed(center),
            )
            self.orbit.store(
                index: base + ORBIT_META_INDEX,
                value: PackedReference::from_metadata(i + 1, pending_anchor.limit),
            )
            let published: bool = escaped || i >= pending_anchor.limit
            let next_control: ReferenceControl = if published {
                ReferenceControl::publish(bank, i, z.re.sign, z.im.sign, s.clock)
            } else {
                store_reference_checkpoint(self.reference_words, z)
                control.advance_pending(i, z.re.sign, z.im.sign)
            }
            self.reference.store(index: 0, value: next_control)
            // Checkpoints belong to the orbit actually selected for preview.
            // During live input that can still be the active bank while its
            // replacement is being built in the other bank.
            let preview_bank: u32 = next_control.preview_bank(s)
            let preview_anchor: ReferenceAnchor = self.anchor.load(index: preview_bank)
            let next_preview: PreviewCache = previous_preview.sync_with_view(
                s,
                next_control,
                preview_anchor.generation,
                budget,
            )
            self.preview_cache.store(index: 0, value: next_preview)
            let synced_view: ViewCache = previous.sync_for_frame(
                s,
                next_control,
                next_preview,
                initial,
            )
            let next_view: ViewCache = if published {
                synced_view.invalidate_for_new_reference()
            } else {
                synced_view
            }
            self.cache.store(index: 0, value: next_view)
        }
        // Integer center differences are camera work, not per-pixel work.
        // Refresh both live banks after building/publishing the reference.
        let current = self.reference.load(index: 0)
        let full = self.cache.load(index: 1)
        let initial = self.cache.load(index: 2)
        let history = HistoryOffsets::for_view(s, full, initial)
        let mut preview = self.preview_cache.load(index: 0)
        preview.history = history
        self.preview_cache.store(index: 0, value: preview)
        let mut bank: u32 = 0
        while bank < 2 {
            let active = current.active_valid == 1 && bank == current.active
            let pending = current.pending == 1 && bank == 1 - current.active
            if active || pending {
                let offset = self.anchor.load(index: bank).delta_from(s)
                let index = bank * 8195 + ORBIT_META_INDEX
                let metadata = self.orbit.load(index: index)
                self.orbit.store(index: index, value: metadata.with_center_offset(offset))
            }
            bank = bank + 1
        }
    }

    fn advance_preview(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).preview_dirty == 0 {
            return
        }
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 1 || preview.step_target == 0 {
            return
        }
        let s: MandelbrotViewState = self.state
        let x: u32 = invocation.global.x
        let y: u32 = invocation.global.y
        let px: i32 = to_i32(from_i32(__bitcast<u32, i32>(x)) * s.camera.res / 256.0)
        let py: i32 = to_i32(from_i32(__bitcast<u32, i32>(y)) * s.camera.res / 256.0)
        if !s.is_input_settled() {
            let tap: ReprojectionTap = reproject_coarse_pixel(
                s,
                self.cache.load(index: 1),
                self.cache.load(index: 2),
                preview.history,
                px,
                py,
            )
            if tap.reusable {
                return
            }
        }
        let index: u32 = (y << 8) | x
        let old: OrbitProgress = self.preview_progress.load(index: index)
        let saved: OrbitProgress = if old.epoch == preview.epoch {
            old
        } else {
            empty_progress(preview.epoch)
        }
        let done_for_chunk: bool = if saved.is_terminal(preview.budget) {
            true
        } else {
            saved.iteration >= preview.step_target
        }
        if done_for_chunk {
            if old.epoch != preview.epoch {
                self.preview_progress.store(index: index, value: saved)
            }
        } else {
            let next: OrbitProgress = continue_preview_pixel(
                self.orbit,
                preview.reference_bank * 8195,
                s.camera,
                PixelSample::ordered_2x2(px, py),
                preview.step_target,
                preview.step_target,
                preview.prefix_only == 1,
                saved,
            )
            self.preview_progress.store(index: index, value: next)
        }
    }

    fn render_preview(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).preview_dirty == 0 {
            return
        }
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.step_target == 0 {
            return
        }
        let s: MandelbrotViewState = self.state
        let x: u32 = invocation.global.x
        let y: u32 = invocation.global.y
        let index: u32 = (y << 8) | x
        let px: i32 = to_i32(from_i32(__bitcast<u32, i32>(x)) * s.camera.res / 256.0)
        let py: i32 = to_i32(from_i32(__bitcast<u32, i32>(y)) * s.camera.res / 256.0)
        let tap: ReprojectionTap = reproject_coarse_pixel(
            s,
            self.cache.load(index: 1),
            self.cache.load(index: 2),
            preview.history,
            px,
            py,
        )
        let cached: Color = if tap.use_full {
            sample_snapshot(self.snapshot_pixels, tap.sx, tap.sy, tap.old_res)
        } else {
            let scale: f32 = 256.0 / max(tap.old_res, 1.0)
            sample(self.initial_pixels, tap.sx * scale, tap.sy * scale)
        }
        let live_reusable: bool = if tap.reusable { !s.is_input_settled() } else { false }
        if live_reusable {
            self.pixels.store(index: index, value: cached)
        } else {
            let computed: OrbitProgress = self.preview_progress.load(index: index)
            let known_escaped: bool = computed.epoch == preview.epoch
                && computed.is_escaped()
                && !computed.is_glitched()
            let proven_interior: bool = computed.epoch == preview.epoch
                && !computed.is_escaped()
                && !computed.is_glitched()
                && preview.prefix_only == 0
                && computed.iteration >= preview.budget
            if known_escaped || proven_interior {
                let current: Color = unpack_lab(progress_color(computed))
                let result: Color = if tap.reusable {
                    blend(cached, current, progress(s.input_age(), 60.0, 300.0))
                } else {
                    current
                }
                self.pixels.store(index: index, value: result)
            } else if tap.reusable {
                self.pixels.store(index: index, value: cached)
            } else if preview.prefix_only == 0 && computed.is_glitched() {
                self.pixels.store(index: index, value: unpack_lab(interior()))
            } else {
                self.pixels.store(index: index, value: Color::default())
            }
        }
    }

    fn finish_preview(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        if self.cache.load(index: 0).preview_dirty == 0 {
            return
        }
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 1 || preview.step_target == 0 {
            return
        }
        let s: MandelbrotViewState = self.state
        let full: ViewCache = self.cache.load(index: 1)
        let initial: ViewCache = self.cache.load(index: 2)
        if !s.is_input_settled() && (full.completed == 1 || initial.completed == 1) {
            return
        }
        self.preview_cache.store(index: 0, value: preview.commit_step())
    }

    // Preserve the first settled preview before native refinement finishes.
    // Neither this image nor its camera metadata changes while input is live.
    fn cache_initial(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let c: ViewCache = self.cache.load(index: 0)
        let old: ViewCache = self.cache.load(index: 2)
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 0 || !ref_state.can_publish_initial(s, c.epoch, old.epoch) {
            return
        }
        let index: u32 = (invocation.global.y << 8) | invocation.global.x
        self.initial_pixels.store(
            index: index,
            value: self.pixels.load(index: index),
        )
    }

    fn publish_initial(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let c: ViewCache = self.cache.load(index: 0)
        let old: ViewCache = self.cache.load(index: 2)
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        let preview: PreviewCache = self.preview_cache.load(index: 0)
        if preview.completed == 0 || !ref_state.can_publish_initial(s, c.epoch, old.epoch) {
            return
        }
        self.cache.store(index: 2, value: c.as_published_initial())
    }

    fn blur_horizontal(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).blur_dirty == 0 {
            return
        }
        let sigma: f32 = self.reference.load(index: 0).blur_sigma(self.state)
        self.horizontal.store(
            index: (invocation.global.y << 8) | invocation.global.x,
            value: gaussian(
                self.pixels,
                invocation.global.x,
                invocation.global.y,
                sigma,
                false,
            ),
        )
    }

    fn blur_vertical(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        if self.cache.load(index: 0).blur_dirty == 0 {
            return
        }
        let sigma: f32 = self.reference.load(index: 0).blur_sigma(self.state)
        self.blurred.store(
            index: (invocation.global.y << 8) | invocation.global.x,
            value: gaussian(
                self.horizontal,
                invocation.global.x,
                invocation.global.y,
                sigma,
                true,
            ),
        )
    }

    // Spatially interleaved phases cover the whole image, rather
    // than sweeping rectangles. Each orbit resumes its own saved recurrence.
    fn restore_oracle(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<16, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        if !s.is_input_settled() {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let history: ViewCache = self.cache.load(index: 1)
        let schedule: RefinementSchedule = RefinementSchedule::for_view(s.camera.zoom, s.camera.res)
        if history.completed == 0 || history.budget < schedule.limit {
            return
        }
        if !same_camera(history, c) {
            return
        }
        let pixel: CohortPixel = schedule.rect_pixel(
            c.cursor,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let saved: OrbitProgress = self.progress_pixels.load(index: index)
        if saved.is_presentable_in(c.epoch) {
            return
        }
        let deep: SampleOracle = self.snapshot_oracle.load(index: index)
        if !deep.is_usable() {
            return
        }
        let preserved: OrbitProgress = OrbitProgress::from_oracle(deep, c.epoch, s.clock)
        let base: u32 = progress_color(preserved)
        self.progress_pixels.store(index: index, value: preserved)
        self.native_pixels.store(index: index, value: base)
        let antialiased: u32 = if history.aa == s.antialias {
            self.snapshot_pixels.load(index: index)
        } else {
            base
        }
        self.antialiased_pixels.store(index: index, value: antialiased)
    }

    // A sparse, full-depth lattice reveals real results while the denser
    // checkpoints are still iterating. It shares their persistent buffers.
    fn seed_refinement(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<16, 16, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        if c.cursor >= 16 || c.completed == 1 {
            return
        }
        let lane: u32 = (invocation.global.y % 4) * 4 + invocation.global.x % 4
        let rank: u32 = c.cursor * 16 + lane
        let block: PackedReference = self.orbit.load(index: 16390 + (rank >> 5))
        let pixel: CohortPixel = seed_pixel(
            block,
            rank,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let old: OrbitProgress = self.progress_pixels.load(index: index)
        if old.is_presentable_in(c.epoch) {
            return
        }
        let saved: OrbitProgress = if old.epoch == c.epoch {
            old
        } else {
            empty_progress(c.epoch)
        }
        let limit: u32 = iteration_limit(s.camera.zoom)
        let next: OrbitProgress = continue_pixel(
            self.orbit,
            ref_state.active * 8195,
            s.camera,
            pixel.sample(),
            limit,
            limit,
            saved,
        )
        self.progress_pixels.store(
            index: index,
            value: next.with_fade_start(s.clock),
        )
        let bits: u32 = progress_color(next)
        self.native_pixels.store(index: index, value: bits)
        self.antialiased_pixels.store(index: index, value: bits)
    }

    fn refine_pixels(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<16, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let schedule: RefinementSchedule = RefinementSchedule::for_view(s.camera.zoom, s.camera.res)
        let pixel: CohortPixel = schedule.rect_pixel(
            c.cursor,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let old: OrbitProgress = self.progress_pixels.load(index: index)
        let saved: OrbitProgress = if old.epoch == c.epoch {
            old
        } else {
            empty_progress(c.epoch)
        }
        if saved.is_terminal(schedule.limit) {
            return
        }
        let next: OrbitProgress = continue_pixel(
            self.orbit,
            ref_state.active * 8195,
            s.camera,
            pixel.sample(),
            schedule.limit,
            2048,
            saved,
        )
        // Once terminal, z_re is free to hold the pixel's fade start time.
        let stored: OrbitProgress = if next.is_terminal(schedule.limit) {
            next.with_fade_start(s.clock)
        } else {
            next
        }
        self.progress_pixels.store(index: index, value: stored)
        let bits: u32 = progress_color(next)
        self.native_pixels.store(index: index, value: bits)
        self.antialiased_pixels.store(index: index, value: bits)
    }

    fn antialias_pixels(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let schedule: RefinementSchedule = RefinementSchedule::for_view(s.camera.zoom, s.camera.res)
        let pixel: CohortPixel = schedule.aa_pixel(
            c.cursor,
            invocation.global.x,
            invocation.global.y,
            s.camera.res,
        )
        if !pixel.active {
            return
        }
        let index: u32 = pixel.index()
        let bits: u32 = self.native_pixels.load(index: index)
        let center: Color = unpack_lab(bits)
        let (left_i, right_i, up_i, down_i) = pixel.pixel.clamped_neighbor_indices(s.camera.res)
        let edge: f32 = max(
            max(
                contrast(center, unpack_lab(self.native_pixels.load(index: left_i))),
                contrast(center, unpack_lab(self.native_pixels.load(index: right_i))),
            ),
            max(
                contrast(center, unpack_lab(self.native_pixels.load(index: up_i))),
                contrast(center, unpack_lab(self.native_pixels.load(index: down_i))),
            ),
        )
        if s.antialias >= 0.5 && edge > 0.12 {
            let camera: Camera = s.camera
            let base: u32 = ref_state.active * 8195
            let a: Color = unpack_lab(sample_pixel(
                self.orbit,
                base,
                camera,
                pixel.offset_sample(Vec2 { x: 0.28, y: -0.28 }),
                schedule.limit,
            ))
            let b: Color = unpack_lab(sample_pixel(
                self.orbit,
                base,
                camera,
                pixel.offset_sample(Vec2 { x: -0.28, y: 0.28 }),
                schedule.limit,
            ))
            let averaged: Color = ((center + a) + b) / 3.0
            self.antialiased_pixels.store(
                index: index,
                value: pack_lab(averaged),
            )
        }
    }

    fn finish_refinement(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let ref_state: ReferenceControl = self.reference.load(index: 0)
        if !ref_state.can_refine(s) {
            return
        }
        let c: ViewCache = self.cache.load(index: 0)
        let end: u32 = RefinementSchedule::for_view(s.camera.zoom, s.camera.res).total_steps()
        if c.cursor >= end {
            return
        }
        self.cache.store(index: 0, value: c.advance_cursor(end))
    }

    fn cache_snapshot(self, invocation: ComputeInvocation)
        uses (ComputeSurface<Workgroup<8, 8, 1>, FixedDispatch<32, 32, 1>>)
    {
        let s: MandelbrotViewState = self.state
        let c: ViewCache = self.cache.load(index: 0)
        let snapshot: ViewCache = self.cache.load(index: 1)
        if c.completed == 0 || snapshot.epoch == c.epoch {
            return
        }
        // Copy only on publication. Small dispatch also makes the idle guard
        // cheap; coalesced lanes cover the fixed-stride image in 64 strips.
        let lane: u32 = (invocation.global.y << 8) | invocation.global.x
        let mut strip: u32 = 0
        while strip < 64 {
            let index: u32 = lane + (strip << 16)
            let pixel: Pixel = Pixel {
                x: index & 2047,
                y: index >> 11,
            }
            if pixel.in_extent(s.camera.res) {
                self.snapshot_pixels.store(
                    index: index,
                    value: self.antialiased_pixels.load(index: index),
                )
                let result: OrbitProgress = self.progress_pixels.load(index: index)
                self.snapshot_oracle.store(index: index, value: result.to_oracle())
            }
            strip = strip + 1
        }
    }

    fn publish_snapshot(self)
        uses (ComputeSurface<Workgroup<1, 1, 1>, FixedDispatch<1, 1, 1>>)
    {
        let c: ViewCache = self.cache.load(index: 0)
        if c.completed == 1 {
            self.cache.store(index: 1, value: c)
        }
    }

    fn display_preview(self, px: i32, py: i32) -> i32 uses (FragmentSurface) {
        let s: MandelbrotViewState = self.state
        let pixel: Pixel = Pixel {
            x: __bitcast<i32, u32>(px) & 2047,
            y: __bitcast<i32, u32>(py) & 2047,
        }
        let index: u32 = pixel.native_index()
        let c: ViewCache = self.cache.load(index: 0)
        let reference_state: ReferenceControl = self.reference.load(index: 0)
        let reveal: f32 = sharpness(reference_state.display_age(s))
        let saved: OrbitProgress = self.progress_pixels.load(index: index)
        if saved.is_presentable_in(c.epoch) {
            let bits: u32 = self.antialiased_pixels.load(index: index)
            let amount: f32 = progress(s.clock - saved.fade_started_at(), 0.0, 350.0) * reveal
            if amount >= 1.0 {
                return display_rgba(unpack_lab(bits))
            }
            let coarse: Color = sample(
                self.blurred,
                from_i32(px) * 256.0 / s.camera.res,
                from_i32(py) * 256.0 / s.camera.res,
            )
            return display_rgba(blend(coarse, unpack_lab(bits), amount))
        }
        let coarse: Color = sample(
            self.blurred,
            from_i32(px) * 256.0 / s.camera.res,
            from_i32(py) * 256.0 / s.camera.res,
        )
        let stride: f32 = from_i32(to_i32((s.camera.res + 511.0) / 512.0))
        let tap: BilinearTap = lattice_tap(px, py, stride, s.camera.res - 1.0)
        let a: OrbitProgress = self.progress_pixels.load(index: tap.i00)
        let b: OrbitProgress = self.progress_pixels.load(index: tap.i10)
        let d: OrbitProgress = self.progress_pixels.load(index: tap.i01)
        let e: OrbitProgress = self.progress_pixels.load(index: tap.i11)
        let ready: bool = a.is_presentable_in(c.epoch)
            && b.is_presentable_in(c.epoch)
            && d.is_presentable_in(c.epoch)
            && e.is_presentable_in(c.epoch)
        if ready {
            let sparse: Color = blend_corners(
                unpack_lab(self.native_pixels.load(index: tap.i00)),
                unpack_lab(self.native_pixels.load(index: tap.i10)),
                unpack_lab(self.native_pixels.load(index: tap.i01)),
                unpack_lab(self.native_pixels.load(index: tap.i11)),
                tap.tx,
                tap.ty,
            )
            let latest_fade: f32 = finite_max(
                finite_max(a.fade_started_at(), b.fade_started_at()),
                finite_max(d.fade_started_at(), e.fade_started_at()),
            )
            let since: f32 = s.clock - latest_fade
            display_rgba(blend(coarse, sparse, progress(since, 0.0, 350.0) * reveal))
        } else {
            display_rgba(coarse)
        }
    }

    fn sync_url(self, event: own SurfaceLocationEvent) -> SurfaceStateEnvelope
        uses (SurfaceLocationTransition)
    {
        SurfaceStateEnvelope { state: sync_url_state(self.state, event) }
    }

    fn contact(self, event: own SurfaceContactEvent) -> SurfaceStateEnvelope
        uses (SurfaceContactTransition)
    {
        SurfaceStateEnvelope { state: contact_transition(self.state, event) }
    }

    fn navigate(self, event: own SurfaceEvent) -> SurfaceStateEnvelope
        uses (SurfaceTransition, SurfaceScheduling<ContinuousFrames>)
    {
        SurfaceStateEnvelope {
            state: transition(self.state, event),
        }
    }
}

